/* ===== game.js ===== */

// ==========================================
// VELOCIDAD CONSTANTE (60 ticks/s) EN CUALQUIER PANTALLA
// ==========================================
// El juego avanza "por cuadro" (sin tiempo real). En teléfonos de 90/120/144 Hz requestAnimationFrame
// llama el bucle 1.5-2.4 veces más seguido y TODO (menú, enemigos, balas, música sincronizada) iba
// más rápido. Este limitador deja pasar solo los cuadros necesarios con un acumulador de tiempo, de modo
// que cada bucle (menuLoop, gameLoop, ...) corra a 60 ticks por segundo de media sin importar el Hz.
// Los callbacks de un solo uso (funciones anónimas nuevas) y los que ya usan su propio dt no se ven afectados.
(function () {
    if (window.__rafLimited) return; window.__rafLimited = true;
    const nativeRAF = window.requestAnimationFrame.bind(window);
    const nativeCAF = window.cancelAnimationFrame.bind(window);
    const STEP = 1000 / 60, MIN = STEP - 1.4;
    const state = new WeakMap();          // callback -> { last, acc }
    const live = new Map();               // id público -> id nativo vigente (para poder cancelar)
    let nextId = 1;
    window.requestAnimationFrame = function (cb) {
        if (typeof cb !== 'function') return nativeRAF(cb);
        const id = nextId++;
        const tick = function (ts) {
            let st = state.get(cb);
            if (!st) { st = { last: ts, acc: STEP }; state.set(cb, st); }      // primer cuadro: pasa directo
            const dt = Math.min(100, Math.max(0, ts - st.last)); st.last = ts;
            st.acc += dt;
            if (st.acc < MIN) { live.set(id, nativeRAF(tick)); return; }      // cuadro de sobra (pantalla >60 Hz): se salta
            st.acc -= STEP; if (st.acc > STEP) st.acc = STEP; if (st.acc < -STEP) st.acc = -STEP;   // el sobrante negativo se conserva: promedio exacto de 60/s
            live.delete(id);
            cb(ts);
        };
        live.set(id, nativeRAF(tick));
        return id;
    };
    window.cancelAnimationFrame = function (id) {
        if (live.has(id)) { nativeCAF(live.get(id)); live.delete(id); } else nativeCAF(id);
    };
    // El escenario del menú (touhou_ui.js) se anima con tiempo real, así que NO necesita el límite de 60 ticks:
    // usa estas versiones nativas para correr a la frecuencia real de la pantalla (90/120/144 Hz).
    window.__nativeRAF = nativeRAF; window.__nativeCAF = nativeCAF;
})();
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const gameContainer = document.getElementById('gameContainer');

ctx.imageSmoothingEnabled = false; 

// ==========================================
// MODO RENDIMIENTO (compatibilidad con gama baja)
// ==========================================
// Detección heurística de un dispositivo "flojo": pocos núcleos de CPU,
// poca RAM reportada, o un móvil de pantalla pequeña. No es exacta, pero
// sirve para proponer el Modo Rendimiento activado por defecto.
function detectLowEndDevice() {
    const cores = navigator.hardwareConcurrency || 4;
    const mem = navigator.deviceMemory || 4; // Chrome/Android only, undefined en el resto
    const uaMobile = /Android|iPhone|iPad|iPod|Mobile|Windows Phone/i.test(navigator.userAgent);
    const smallScreen = Math.min(window.innerWidth, window.innerHeight) < 700;
    return cores <= 4 || mem <= 2 || (uaMobile && smallScreen && cores <= 6);
}

let performanceMode = detectLowEndDevice();
// Factor de reducción de partículas/efectos cuando el modo rendimiento está activo.
const PERF_PARTICLE_SCALE = 0.35;
function perfCount(n) {
    return performanceMode ? Math.max(1, Math.round(n * PERF_PARTICLE_SCALE)) : n;
}

// Aclara (percent > 0) u oscurece (percent < 0) un color hexadecimal '#rrggbb'.
// Se usa para sacar automáticamente el tono de luz/sombra de cada nave del jugador
// a partir de un único color base, sin tener que declarar 3 colores a mano por nave.
function shadeColor(hex, percent) {
    let num = parseInt(hex.replace('#', ''), 16);
    let r = Math.max(0, Math.min(255, (num >> 16) + Math.round(2.55 * percent)));
    let g = Math.max(0, Math.min(255, ((num >> 8) & 0x00FF) + Math.round(2.55 * percent)));
    let b = Math.max(0, Math.min(255, (num & 0x0000FF) + Math.round(2.55 * percent)));
    return '#' + (0x1000000 + r * 0x10000 + g * 0x100 + b).toString(16).slice(1);
}

// ==========================================
// LAYOUT RESPONSIVE
// ==========================================
let playAreaH = 600;          
let hudPosition = 'side';     
let hudSize = 270;            
let isPortraitMode = false;
let isVerticalMode = false; // Modo vertical estilo Touhou (solo PC, ver optVerticalMode)
let viewScale = 1;          // pantalla real / lienzo lógico (< 1 en teléfono horizontal)
const MOBILE_ZOOM_OUT = 1.25;      // cuánto más "grande" es el mundo lógico en teléfono horizontal (1 = como antes)
const MOBILE_LOGICAL_MAX_H = 520;  // tope del alto lógico

function computeLayout() {
    const w = window.innerWidth;
    const h = window.innerHeight;
    const isMobileNow = optMobile.checked;

    if (currentMode === 'clasico') {
        const targetRatio = 4 / 3;
        const maxW = Math.min(w * 0.96, 1000);
        const maxH = Math.min(h * 0.96, 750);
        let boxW = maxW;
        let boxH = boxW / targetRatio;
        if (boxH > maxH) { boxH = maxH; boxW = boxH * targetRatio; }
        boxW = Math.round(boxW); boxH = Math.round(boxH);

        gameContainer.style.width = boxW + 'px';
        gameContainer.style.height = boxH + 'px';
        gameContainer.style.transform = 'none';
        canvas.style.width = ''; canvas.style.height = ''; viewScale = 1;
        canvas.width = boxW;
        canvas.height = boxH;

        hudPosition = 'none'; hudSize = 0; isPortraitMode = false;
        playAreaW = canvas.width; playAreaH = canvas.height;

        if (typeof player !== 'undefined' && player) {
            player.x = Math.min(player.x, Math.max(0, playAreaW - player.width));
            player.y = Math.min(player.y, Math.max(0, playAreaH - player.height));
        }
        if (mobileControls) { mobileControls.style.paddingBottom = '30px'; }
        isVerticalMode = false;
        return;
    }

    // Modo Vertical estilo Touhou: solo disponible en PC (nunca en el modo teléfono).
    // Recrea el formato clásico de shmup vertical: área de juego en retrato, centrada,
    // con el panel de puntaje/vidas fijo a su derecha, tal como en los juegos de Touhou.
    if (!isMobileNow && optVerticalMode.checked) {
        isVerticalMode = true;
        const PORTRAIT_RATIO = 3 / 4; // ancho/alto del área jugable
        let areaH = Math.min(h * 0.96, 900);
        let areaW = areaH * PORTRAIT_RATIO;
        let vHudW = Math.max(200, Math.min(240, areaW * 0.62));
        let boxW = areaW + vHudW;
        if (boxW > w * 0.98) {
            let scale = (w * 0.98) / boxW;
            areaW *= scale; areaH *= scale; vHudW *= scale; boxW = areaW + vHudW;
        }
        areaW = Math.round(areaW); areaH = Math.round(areaH); vHudW = Math.round(vHudW);
        boxW = areaW + vHudW;

        gameContainer.style.width = boxW + 'px';
        gameContainer.style.height = areaH + 'px';
        gameContainer.style.transform = 'none';
        canvas.style.width = ''; canvas.style.height = ''; viewScale = 1;
        canvas.width = boxW;
        canvas.height = areaH;

        hudPosition = 'side'; hudSize = vHudW; isPortraitMode = false;
        playAreaW = areaW; playAreaH = areaH;

        if (typeof player !== 'undefined' && player) {
            player.x = Math.min(player.x, Math.max(0, playAreaW - player.width));
            player.y = Math.min(player.y, Math.max(0, playAreaH - player.height));
        }
        if (mobileControls) { mobileControls.style.paddingBottom = '30px'; }
        return;
    }
    isVerticalMode = false;

    gameContainer.style.width = w + 'px';
    gameContainer.style.height = h + 'px';
    gameContainer.style.transform = 'none';

    const isMobile = isMobileNow;
    isPortraitMode = isMobile && h > w;

    // TELÉFONO HORIZONTAL: el juego estaba diseñado para ~600 px de alto; en un móvil de 360-420 px todo
    // (naves, hadas, balas, textos) se veía enorme y quedaba poco espacio para esquivar. Ahora el lienzo usa
    // una resolución LÓGICA mayor (~25 % más) y el navegador lo ajusta a la pantalla: los sprites se ven más
    // chicos y proporcionados, el área de juego es más amplia y nada cambia en la lógica (el hitbox sigue igual).
    // Los toques usan coordenadas de pantalla/ratio del lienzo, así que el escalado no los afecta.
    let logicalW = w, logicalH = h;
    if (isMobile && !isPortraitMode && h < 540) {
        logicalH = Math.round(Math.min(MOBILE_LOGICAL_MAX_H, h * MOBILE_ZOOM_OUT));
        logicalW = Math.round(w * logicalH / h);
        canvas.style.width = '100%'; canvas.style.height = '100%';
    } else {
        canvas.style.width = ''; canvas.style.height = '';
    }
    viewScale = h / logicalH;
    canvas.width = logicalW;
    canvas.height = logicalH;

    if (isPortraitMode && window.HudPhone && HudPhone.active()) {
        // v52: HUD compacto arriba (hud_telefono.js): ya no se reserva la franja de abajo, donde van los pulgares
        hudPosition = 'none'; hudSize = 0;
        playAreaW = canvas.width;
        playAreaH = canvas.height;
    } else if (isPortraitMode) {
        hudPosition = 'bottom';
        hudSize = Math.round(Math.max(120, Math.min(190, h * 0.24)));
        playAreaW = canvas.width;
        playAreaH = canvas.height - hudSize;
    } else {
        hudPosition = 'side';
        hudSize = Math.round(optWidescreen.checked
            ? Math.max(200, Math.min(280, canvas.width * 0.18))
            : Math.max(230, Math.min(320, canvas.width * 0.26)));
        // en teléfono horizontal el panel lateral es más angosto: más pantalla para jugar
        if (isMobile && viewScale < 1) hudSize = Math.round(Math.max(196, Math.min(232, canvas.width * 0.19)));
        playAreaW = canvas.width - hudSize;
        playAreaH = canvas.height;
    }

    if (typeof player !== 'undefined' && player) {
        player.x = Math.min(player.x, Math.max(0, playAreaW - player.width));
        player.y = Math.min(player.y, Math.max(0, playAreaH - player.height));
    }

    if (mobileControls) {
        mobileControls.style.paddingBottom = (hudPosition === 'bottom' ? hudSize + 20 : 30) + 'px';
    }
}
function fitGameToScreen() { computeLayout(); }
window.addEventListener('resize', fitGameToScreen);
window.addEventListener('orientationchange', () => setTimeout(fitGameToScreen, 300));

// ==========================================
// CONFIGURACIÓN DE MÚSICA (OPTIMIZADA)
// ==========================================
// Todas las pistas viven en la carpeta /musica (ver musica/LEEME.txt):
//   nivelN_oleada.mp3 (oleadas + mini jefe) · nivelN_jefe.mp3 (solo el jefe final)   (N = 1..7)
// Si falta alguna pista el juego NO falla: usa la siguiente de su lista de respaldo
// (al final, por_defecto_oleada.mp3 / por_defecto_jefe.mp3, las de siempre).
const MUSIC_DIR = 'musica/';
let bgmVolume = 0.25;
const musicCache = {};
// ---- LOOP PERFECTO: las pistas se reproducen con Web Audio (AudioBufferSource con loop), que repite sin
// el pequeño corte del <audio loop>. Además se recorta el silencio digital del principio y del final del mp3
// (el relleno que añaden los codificadores), que es lo que hacía notar el salto. Si el navegador no puede
// decodificarlo (p. ej. abriendo el juego como archivo local) se usa el <audio> normal como respaldo.
let _musicCtx = null;
function getMusicCtx() {
    if (!_musicCtx) { const AC = window.AudioContext || window.webkitAudioContext; if (AC) { try { _musicCtx = new AC(); } catch (e) {} } }
    return _musicCtx;
}
['pointerdown', 'keydown', 'touchstart', 'click'].forEach(ev => window.addEventListener(ev, () => {
    const c = _musicCtx; if (c && c.state === 'suspended') { try { c.resume().catch(() => {}); } catch (e) {} }
}, { passive: true }));
const musicLRU = [];                       // pistas decodificadas; se liberan las menos usadas para no gastar memoria
function touchTrack(t) {
    const i = musicLRU.indexOf(t); if (i >= 0) musicLRU.splice(i, 1);
    musicLRU.push(t);
    let n = 0; for (const x of musicLRU) if (!x._pin) n++;
    for (let k = 0; k < musicLRU.length && n > 4; ) {
        const x = musicLRU[k];
        if (x !== t && !x._pin && x._unload()) { musicLRU.splice(k, 1); n--; } else k++;
    }
}
class LoopTrack {
    constructor(file, pin) {
        this.file = file; this.url = MUSIC_DIR + file; this._pin = !!pin;
        this._ok = null; this._vol = bgmVolume; this._want = false; this._playing = false;
        this._buf = null; this._src = null; this._gain = null;
        this._pos = 0; this._startPos = 0; this._startedAt = 0; this._ls = 0; this._le = 0; this._el = null;
        this._load();
    }
    _load() {
        const ctx = getMusicCtx();
        if (!ctx || typeof fetch !== 'function') { this._fallback(); return; }
        fetch(this.url)
            .then(r => { if (!r.ok) throw new Error('http ' + r.status); return r.arrayBuffer(); })
            .then(ab => new Promise((res, rej) => { const p = ctx.decodeAudioData(ab, res, rej); if (p && p.then) p.then(res, rej); }))
            .then(buf => this._setBuffer(buf))
            .catch(() => this._fallback());
    }
    _setBuffer(buf) {
        const ch = buf.numberOfChannels, n = buf.length, thr = 0.0004, data = [];
        for (let c = 0; c < ch; c++) data.push(buf.getChannelData(c));
        const loud = i => { for (let c = 0; c < ch; c++) if (Math.abs(data[c][i]) > thr) return true; return false; };
        let s = 0, e = n - 1;
        while (s < n && !loud(s)) s++;
        if (s >= n) { s = 0; e = n - 1; } else { while (e > s && !loud(e)) e--; }
        this._buf = buf; this._ls = s / buf.sampleRate; this._le = Math.max(this._ls + 0.05, (e + 1) / buf.sampleRate);
        this._ok = true;
        if (this._want) this._startSrc();
    }
    _fallback() {
        if (this._el) return;
        const a = new Audio(); a.loop = true; a.volume = Math.max(0, Math.min(1, this._vol)); a.preload = 'auto';
        a.addEventListener('canplay', () => { this._ok = true; });
        a.addEventListener('error', () => { this._ok = false; });
        a.src = this.url; this._el = a;
        if (this._want) { const p = a.play(); if (p && p.catch) p.catch(() => {}); }
    }
    get volume() { return this._vol; }
    set volume(v) {
        this._vol = v;
        if (this._gain) this._gain.gain.value = v;
        if (this._el) this._el.volume = Math.max(0, Math.min(1, v));
    }
    get paused() { return this._el ? this._el.paused : !this._playing; }
    get currentTime() {
        if (this._el) return this._el.currentTime;
        if (!this._playing) return this._pos;
        const c = getMusicCtx(); let p = this._startPos + (c.currentTime - this._startedAt);
        const len = this._le - this._ls;
        if (p >= this._le && len > 0) p = this._ls + ((p - this._ls) % len);
        return p;
    }
    set currentTime(t) {
        if (this._el) { try { this._el.currentTime = t; } catch (e) {} return; }
        this._pos = t;
        if (this._playing) { this._stopSrc(false); this._startSrc(); }
    }
    play() {
        this._want = true;
        if (this._el) return this._el.play();
        const c = getMusicCtx(); if (!c) return Promise.reject(new Error('sin audio'));
        if (c.state === 'suspended') return c.resume().then(() => this._startSrc());
        this._startSrc(); return Promise.resolve();
    }
    pause() {
        this._want = false;
        if (this._el) { this._el.pause(); return; }
        this._stopSrc(true);
    }
    _startSrc() {
        const c = getMusicCtx();
        if (!c || !this._want || this._src || !this._buf) return;
        if (!this._gain) { this._gain = c.createGain(); this._gain.connect(c.destination); }
        this._gain.gain.value = this._vol;
        const src = c.createBufferSource();
        src.buffer = this._buf; src.loop = true; src.loopStart = this._ls; src.loopEnd = this._le;
        src.connect(this._gain);
        let off = this._pos;
        if (off < this._ls || off >= this._le) off = this._ls + (Math.max(off - this._ls, 0) % (this._le - this._ls));
        src.start(0, off);
        this._src = src; this._startPos = off; this._startedAt = c.currentTime; this._playing = true;
        touchTrack(this);
    }
    _stopSrc(save) {
        if (!this._src) return;
        if (save) this._pos = this.currentTime;
        try { this._src.stop(); this._src.disconnect(); } catch (e) {}
        this._src = null; this._playing = false;
    }
    _unload() {
        if (this._playing || this._want || this._pin) return false;
        this._buf = null; this._ok = null; delete musicCache[this.file];
        return true;
    }
}
function loadTrack(file) {
    if (musicCache[file]) return musicCache[file];
    const a = new LoopTrack(file, file === 'menu.mp3');
    musicCache[file] = a;
    return a;
}
function setBgmVolume(g) {
    bgmVolume = g;
    Object.keys(musicCache).forEach(k => { try { musicCache[k].volume = g; } catch (e) {} });
}
// Devuelve la primera pista de la lista que exista (las que fallaron al cargar se saltan).
function pickTrack(files) {
    for (let i = 0; i < files.length; i++) {
        const t = loadTrack(files[i]);
        if (t._ok !== false) return t;
    }
    return null;
}
// MENÚ: si existe musica/menu.mp3 suena esa canción en el menú (si no, se queda la música de ambiente generada).
const bgmMenu = loadTrack('menu.mp3');
function menuMp3Ready() { return bgmMenu._ok === true; }

let currentBGM = null;

function playMusic(track) {
    if (currentBGM !== track) {
        if (currentBGM) { 
            currentBGM.pause(); 
            currentBGM.currentTime = 0; 
        }
        currentBGM = track;
        if (currentBGM) {
            currentBGM.currentTime = 0;
            let playPromise = currentBGM.play();
            if (playPromise !== undefined) {
                playPromise.catch(error => {
                    console.log("El navegador bloqueó la reproducción automática de audio (o falta el archivo):", error);
                });
            }
        }
    }
}

function stopMusic() {
    if (currentBGM) {
        currentBGM.pause();
        currentBGM.currentTime = 0;
        currentBGM = null;
    }
}

// Música por nivel (1..7): las oleadas y el mini jefe comparten la pista nivelN_oleada.mp3; solo el jefe final tiene la suya.
function updateMusicState() {
    if (!isPlaying || currentMode === 'clasico') {
        stopMusic();
        return;
    }
    const n = currentLevelIndex() + 1;
    let files;
    // Jefe secreto EL INVASOR (invasor.js): suena musica/invasor.mp3; al caer, se calla para la pantalla de victoria.
    if (window.InvaderBoss && activeBoss instanceof window.InvaderBoss) {
        if (activeBoss.state === 'dead') { stopMusic(); return; }
        files = ['invasor.mp3', 'nivel' + n + '_jefe.mp3', 'por_defecto_jefe.mp3'];
    } else if (activeBoss && activeBoss.state !== 'dead') {
        files = ['nivel' + n + '_jefe.mp3', 'por_defecto_jefe.mp3'];
    } else {   // oleadas Y mini jefe: la misma pista de oleada (no se corta ni se reinicia al llegar el mini jefe)
        files = ['nivel' + n + '_oleada.mp3', 'por_defecto_oleada.mp3'];
    }
    playMusic(pickTrack(files));
    // Arreglo: si el navegador rechazó o interrumpió el play() (pasaba con la música del jefe y había que
    // entrar a Opciones para que sonara), se reintenta solo cada ~0,5 s mientras la partida no esté en pausa.
    if (currentBGM && currentBGM.paused && !(window.GamePause && window.GamePause.on) && (++musicRetryT % 30 === 0)) {
        const pp = currentBGM.play(); if (pp && pp.catch) pp.catch(() => {});
    }
}
let musicRetryT = 0;

// ==========================================
// ELEMENTOS DEL MENÚ UI Y MODAL
// ==========================================
const menuUI = document.getElementById('menuUI');
const playBtn = document.getElementById('playBtn');
const playerNameInput = document.getElementById('playerName');
const difficultySelect = document.getElementById('difficulty');
const gameModeSelect = document.getElementById('gameMode');
const scoreList = document.getElementById('scoreList');
const lunaticHint = document.getElementById('lunaticHint');
if (difficultySelect && lunaticHint) {
    const toggleLunaticHint = () => { lunaticHint.style.display = difficultySelect.value === 'lunatico' ? 'block' : 'none'; };
    difficultySelect.addEventListener('change', toggleLunaticHint);
    toggleLunaticHint();
}

const optLives = document.getElementById('optLives');
const optWidescreen = document.getElementById('optWidescreen');
const optMobile = document.getElementById('optMobile');
const optVerticalMode = document.getElementById('optVerticalMode');
const verticalModeLabel = document.getElementById('verticalModeLabel');
const optPerformance = document.getElementById('optPerformance');

// El Modo Vertical (estilo Touhou) es exclusivo de PC: si el Modo Teléfono está
// activo, se desactiva y se bloquea el checkbox para evitar una combinación inválida.
function syncVerticalModeAvailability() {
    if (optMobile.checked) {
        optVerticalMode.checked = false;
        optVerticalMode.disabled = true;
        if (verticalModeLabel) verticalModeLabel.style.opacity = '0.4';
    } else {
        optVerticalMode.disabled = false;
        if (verticalModeLabel) verticalModeLabel.style.opacity = '1';
    }
}
syncVerticalModeAvailability();
optMobile.addEventListener('change', syncVerticalModeAvailability);
// ==========================================
// EFECTO CRT RETRO (ligero)
// ==========================================
// Todo el efecto vive en CSS (#crtOverlay en index.html): líneas de barrido y máscara RGB estáticas,
// viñeta y un destello/barrido muy suaves animados solo con opacity/transform (los maneja la GPU,
// no cuestan nada de CPU). No se usa ningún filtro sobre el canvas. En Modo Rendimiento (o si el
// sistema pide menos animaciones) solo queda la parte estática.
const optCRT = document.getElementById('optCRT');
const crtOverlay = document.getElementById('crtOverlay');
function applyCRT() {
    if (!optCRT || !crtOverlay) return;
    crtOverlay.classList.toggle('hidden', !optCRT.checked);
    crtOverlay.classList.toggle('crt-static', !!performanceMode);
    gameContainer.classList.toggle('crt-on', optCRT.checked);
}
if (optCRT) {
    let savedCRT = null;
    try { savedCRT = localStorage.getItem('sg_crt'); } catch (e) {}
    optCRT.checked = savedCRT === null ? true : savedCRT === '1';
    optCRT.addEventListener('change', () => {
        try { localStorage.setItem('sg_crt', optCRT.checked ? '1' : '0'); } catch (e) {}
        applyCRT();
    });
    applyCRT();
}

const btnFullscreen = document.getElementById('btnFullscreen');
const mobileControls = document.getElementById('mobileControls');

// El checkbox arranca con el valor detectado automáticamente; el jugador
// puede activarlo u forzarlo a desactivarlo manualmente en cualquier momento.
optPerformance.checked = performanceMode;
optPerformance.addEventListener('change', () => {
    performanceMode = optPerformance.checked;
    if (typeof applyCRT === 'function') applyCRT();
    // Si estamos en el menú o en una partida, refresca las capas de fondo
    // para que el nuevo nivel de detalle se note al instante.
    if (typeof currentTheme !== 'undefined') {
        let idx = LEVEL_THEMES.indexOf(currentTheme);
        if (idx >= 0) initLevelTheme(idx + 1);
    }
});

const btnOptionsToggle = document.getElementById('btnOptionsToggle');
const optionsModal = document.getElementById('optionsModal');
const btnCloseOptions = document.getElementById('btnCloseOptions');

btnOptionsToggle.addEventListener('click', () => { 
    optionsModal.classList.remove('hidden'); 
});

btnCloseOptions.addEventListener('click', () => { 
    optionsModal.classList.add('hidden'); 
});

