let currentEnemyFrame = 0;
let enemyAnimTimer = 0;

// ==========================================
// CACHÉ DE RECOLOREADO POR NIVEL
// ==========================================
// Antes se llamaba a ctx.filter = 'hue-rotate(...)...' en CADA enemigo, en
// CADA frame. El filtro de canvas es muy costoso de calcular en tiempo real
// y con varios enemigos y balas en pantalla esto era lo que hacía que el
// juego se sintiera "lento" justo en los momentos de más acción. Ahora el
// resultado de aplicar el filtro se calcula UNA sola vez por (sprite, frame,
// nivel) y se guarda en un canvas aparte; dibujar ese canvas ya coloreado es
// tan barato como dibujar una imagen normal, así que la velocidad de juego
// se mantiene constante sin importar cuántos enemigos haya en pantalla.
const RECOLOR_CACHE = {};
function getRecoloredSprite(cacheKey, img, levelIdx) {
    if (!img.complete || img.naturalWidth === 0) return null;
    let byLevel = RECOLOR_CACHE[cacheKey];
    if (!byLevel) byLevel = RECOLOR_CACHE[cacheKey] = {};
    let cached = byLevel[levelIdx];
    if (cached && cached.srcImg === img) return cached.canvas;
    const off = document.createElement('canvas');
    off.width = img.naturalWidth; off.height = img.naturalHeight;
    const octx = off.getContext('2d');
    octx.imageSmoothingEnabled = false;
    octx.filter = levelEnemyFilter(levelIdx);
    octx.drawImage(img, 0, 0);
    byLevel[levelIdx] = { canvas: off, srcImg: img };
    return off;
}

const audioCtx = new (window.AudioContext || window.webkitAudioContext)();

// Disparo del jugador: el tono base sube ligeramente y se le añade una segunda
// capa (más brillante) a medida que sube el Nivel de Ataque, para que los
// disparos se sientan más "llamativos" e importantes en niveles altos.
function playShootSound() {
    if (audioCtx.state === 'suspended') audioCtx.resume();
    let lvl = (typeof powerLevel !== 'undefined') ? powerLevel : 1;
    let pitchBoost = Math.min(1, (lvl - 1) / 14); // 0 en nivel 1, 1 en nivel MAX

    const osc = audioCtx.createOscillator(); const gain = audioCtx.createGain();
    osc.type = 'square'; osc.connect(gain); gain.connect(audioCtx.destination);
    let startFreq = 880 + pitchBoost * 260;
    osc.frequency.setValueAtTime(startFreq, audioCtx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(110 + pitchBoost * 40, audioCtx.currentTime + 0.1);
    gain.gain.setValueAtTime(0.05, audioCtx.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.1);
    osc.start(); osc.stop(audioCtx.currentTime + 0.1);

    // Capa extra brillante: solo se activa a partir de la mitad del progreso de nivel.
    if (pitchBoost > 0.35) {
        const osc2 = audioCtx.createOscillator(); const gain2 = audioCtx.createGain();
        osc2.type = 'triangle'; osc2.connect(gain2); gain2.connect(audioCtx.destination);
        osc2.frequency.setValueAtTime(startFreq * 1.5, audioCtx.currentTime);
        osc2.frequency.exponentialRampToValueAtTime(220, audioCtx.currentTime + 0.08);
        gain2.gain.setValueAtTime(0.035 * pitchBoost, audioCtx.currentTime);
        gain2.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.08);
        osc2.start(); osc2.stop(audioCtx.currentTime + 0.08);
    }
}

// Impacto "seco": un golpe corto y suave, para una bala que ROZA a un enemigo/jefe
// sin matarlo. Distinto del estallido grande de playExplosionSound, para que no
// suene como si todo lo que se toca en pantalla estuviera explotando.
function playHitSound() {
    if (audioCtx.state === 'suspended') audioCtx.resume();
    const osc = audioCtx.createOscillator(); const gain = audioCtx.createGain();
    osc.type = 'triangle'; osc.connect(gain); gain.connect(audioCtx.destination);
    osc.frequency.setValueAtTime(520, audioCtx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(180, audioCtx.currentTime + 0.06);
    gain.gain.setValueAtTime(0.09, audioCtx.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.06);
    osc.start(); osc.stop(audioCtx.currentTime + 0.06);
}

function playExplosionSound() {
    if (audioCtx.state === 'suspended') audioCtx.resume();
    const osc = audioCtx.createOscillator(); const gain = audioCtx.createGain();
    osc.type = 'sawtooth'; osc.connect(gain); gain.connect(audioCtx.destination);
    osc.frequency.setValueAtTime(100, audioCtx.currentTime); osc.frequency.exponentialRampToValueAtTime(10, audioCtx.currentTime + 0.4);
    gain.gain.setValueAtTime(0.15, audioCtx.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.4);
    osc.start(); osc.stop(audioCtx.currentTime + 0.4);
}

// Sonido de "¡Nivel de Ataque subido!": un arpegio corto ascendente, más festivo
// que cualquier otro sonido del juego, para que subir de nivel se sienta especial.
function playLevelUpSound() {
    if (audioCtx.state === 'suspended') audioCtx.resume();
    const notes = [523.25, 659.25, 783.99, 1046.5]; // C5 E5 G5 C6
    notes.forEach((freq, i) => {
        const osc = audioCtx.createOscillator(); const gain = audioCtx.createGain();
        osc.type = 'square'; osc.connect(gain); gain.connect(audioCtx.destination);
        let t = audioCtx.currentTime + i * 0.07;
        osc.frequency.setValueAtTime(freq, t);
        gain.gain.setValueAtTime(0.0001, t);
        gain.gain.exponentialRampToValueAtTime(0.08, t + 0.02);
        gain.gain.exponentialRampToValueAtTime(0.001, t + 0.16);
        osc.start(t); osc.stop(t + 0.16);
    });
}

let isPlaying = false;
let score = 0;
let lives = 3;
const MAX_LIVES = 10; // Tope máximo de vidas, tanto en opciones como en gameplay
