let invulnerableUntil = 0; 
let currentMode = 'moderno';
let playAreaW = 800; 
let hiScore = 0;

let classicEnemies = [];
let bunkers = [];
let classicEnemyDir = 1;

let powerUps = { shield: 0, doubleFire: 0, paralyze: 0, superShot: 0 };
let isCharging = false;
let chargeStart = 0;

let powerPoints = 0;
let grazePoints = 0;
const GRAZE_MAX = 230; // Puntos de graze necesarios para activar la bomba (antes 350)
let mPromptActive = false;   // v27: = "hay al menos 1 bomba en el stock" (todos los HUD lo siguen usando)
// v27: STOCK DE BOMBAS (máx. 4). Cada GRAZE_MAX puntos de graze rellenan 1 bomba; useBomb() gasta 1.
const BOMB_MAX = 4;
let bombStock = 0;
function setBombStock(n) {
    bombStock = Math.max(0, Math.min(BOMB_MAX, n | 0));
    mPromptActive = bombStock > 0;
    try { if (!mPromptActive) document.getElementById('btnBomb').classList.remove('bomb-ready'); } catch (e) {}
}
function addGraze(n) {
    if (bombStock >= BOMB_MAX) { grazePoints = 0; return; }              // stock lleno: el graze ya no se acumula
    grazePoints += n;
    let gained = false;
    while (grazePoints >= GRAZE_MAX && bombStock < BOMB_MAX) { grazePoints -= GRAZE_MAX; setBombStock(bombStock + 1); gained = true; }
    if (bombStock >= BOMB_MAX) grazePoints = 0;
    if (gained) { try { playShootSound(); } catch (e) {} }
}
const bombFrac = () => (bombStock >= BOMB_MAX ? 1 : Math.max(0, Math.min(1, grazePoints / GRAZE_MAX)));   // progreso hacia la siguiente bomba
let bombEffect = { active: false, radius: 0, maxRadius: 0, x: 0, y: 0 }; 

let partnerPoints = 0;
let partners = [];
let screenShake = 0;

let powerLevel = 1;
// v16: contadores de la partida actual (ítems, powerups, enemigos, bombas...). Los guarda perfil.js al terminar la partida.
let runStats = {};
function runStat(k, n) { runStats[k] = (runStats[k] || 0) + (n === undefined ? 1 : n); }
let practiceStage = 0;        // Modo Práctica: 0 = partida normal, 1..7 = nivel que se está practicando (ver touhou_ui.js)
const MAX_CONTINUES = 2;      // intentos extra para revivir al quedarte sin vidas
let continuesLeft = MAX_CONTINUES;
let reviveAnim = null;        // animación de revivir: los pedazos de la nave se juntan sobre fondo negro
let lastDeathData = null;     // sprite y pedazos de la última muerte (los reutiliza la animación de revivir)
let deathAnim = null;         // animación de muerte (nave que se rompe, estilo Undertale)
let continueState = null;     // { t, snap, ... } mientras se muestra la pantalla de CONTINUAR
let enemiesDefeatedForPower = 0;
const KILLS_PER_LEVEL = 65; // Cada 65 enemigos derrotados sube el Nivel de Ataque
const MAX_POWER_LEVEL = 15;
let levelUpFlash = 0; // frames restantes mostrando el aviso de "subida de nivel"

// DEFENSA / DIFICULTAD ESCALABLE
// Los enemigos comunes, mini jefes y jefes aguantan más golpes a medida que:
//   1) avanzas de nivel (cada nivel que pasa suma defensa), y
//   2) subes tu Nivel de Ataque (mientras más poderoso eres, más duros se vuelven).
// Los factores se MULTIPLICAN y dividen el daño que recibe el enemigo. Ajusta estas constantes
// para balancear: más alto = más difícil.
const DEF_PER_LEVEL_ENEMY = 0.26;   // v31: +26 % de defensa por cada nivel que pasa (enemigos comunes) (antes 0.18)
const DEF_PER_ATTACK_ENEMY = 0.10;  // v31: +10 % por cada Nivel de Ataque (antes 0.07)
const DEF_PER_PARTNER_ENEMY = 0.10; // v31: +10 % por cada partner activo (los partners suman mucho daño)
const DEF_DOUBLEFIRE_ENEMY = 1.30;  // v31: mientras dura el power-up de disparo doble
const DEF_SUPERSHOT_ENEMY = 1.15;   // v31: mientras dura el super disparo
// v33: ALIVIO en los niveles 5, 6 y 7 (Difícil y Lunático): la defensa total de los enemigos comunes se multiplica por este valor
// (0.40 = tienen ~60 % menos defensa que antes). Pon 1 para quitarlo. Nunca baja de 1 (siempre mueren de algún golpe).
const LATE_LEVEL_DEF_MULT = { dificil: 0.50, lunatico: 0.38 };
const LATE_LEVEL_FROM = 4;               // desde el nivel 5 el alivio es completo; el nivel 4 lo recibe a medias (transición suave, sin saltos raros)
const DEF_PER_LEVEL_BOSS = 0.10;    // jefes y mini jefes: menos por nivel porque su vida ya sube por nivel
const DEF_PER_ATTACK_BOSS = 0.05;
const POWERUP_DROP_LOSS_PER_LEVEL = 0.05;   // cada nivel baja ~5 % la probabilidad de soltar power-ups
const POWERUP_DROP_LOSS_PER_ATTACK = 0.02;  // y cada Nivel de Ataque ~2 % más
const POWERUP_DROP_MIN = 0.35;              // nunca baja de 35 % de la probabilidad original
function levelDefenseStep() { return Math.min(Math.max(currentWave, 1), 10) - 1; }
// LUNÁTICO: los enemigos comunes tienen +30 % de defensa extra (1.3). Pon 1 para quitarlo.
const LUNATIC_ENEMY_DEF_BONUS = 1.3;
// LUNÁTICO (niveles 1-7): los enemigos comunes tienen +18 % de vida, +18 % de cadencia de disparo y +18 % de velocidad de descenso.
// Cambia el 1.18 para ajustarlo (1 = sin bonus). No afecta a jefes ni mini jefes.
const LUNATIC_ENEMY_BOOST = 1.18;
// v31: enemigos comunes disparan más rápido (0.74 = ~35 % más disparos) y con balas algo más veloces. Pon 1 / 0.72 para volver a lo de antes.
const ENEMY_CADENCE_MULT = 0.74;
const ENEMY_BULLET_SPEED_MULT = 0.80;
// LUNÁTICO · jefes y mini jefes: +30 % de vida (LUNATIC_BOSS_HP_BOOST). Al quitarles la mitad de la vida entran en MODO DEFENSA:
// reciben 35 % menos daño (LUNATIC_DEFENSE_MODE_MULT = 0.65), usan sus habilidades más poderosas y descansan menos entre ellas.
const LUNATIC_BOSS_HP_BOOST = 1.30;
const LUNATIC_DEFENSE_MODE_MULT = 0.65;
// v28 · AJUSTE DE VIDA DE JEFES (feedback: demasiada vida en los últimos niveles de Difícil y Lunático).
// Multiplica la vida del JEFE FINAL (BOSS_HP_TUNE) y del MINI JEFE (MINI_HP_TUNE) según dificultad y nivel.
// Un valor por nivel: [N1, N2, N3, N4, N5, N6, N7]. 1 = sin cambio; 0.7 = 30 % menos vida. Fácil, Medio y Clásico no cambian.
// En el Modo Infinito los niveles 8+ usan el valor del nivel 7. El jefe secreto (invasor.js) puede llamar a window.bossHpTune(hp, nivel).
const BOSS_HP_TUNE = {
    dificil:  [1, 1, 1, 0.86, 0.70, 0.66, 0.85],
    lunatico: [1, 1, 1, 0.68, 0.52, 0.46, 0.66]
};
const MINI_HP_TUNE = {
    dificil:  [1, 1, 1, 0.88, 0.78, 0.72, 0.90],
    lunatico: [1, 1, 1, 0.70, 0.60, 0.52, 0.76]
};
function bossHpTune(hp, waveNum, isMini) {
    if (currentMode === 'clasico') return hp;
    const t = (isMini ? MINI_HP_TUNE : BOSS_HP_TUNE)[currentDiff];
    if (!t) return hp;
    return Math.max(1, Math.round(hp * t[Math.min(Math.max(waveNum, 1), t.length) - 1]));
}
window.bossHpTune = bossHpTune;
function lunaticBossMode() { return currentDiff === 'lunatico' && currentMode !== 'clasico'; }
function lunaticEnemyBoost() { return (currentDiff === 'lunatico' && currentMode !== 'clasico') ? LUNATIC_ENEMY_BOOST : 1; }
function enemyDefenseFactor(e) {
    if (currentMode === 'clasico') return 1;
    if (e && e.isMinion) return 1;                                   // los esbirros de mini jefe mueren de un golpe
    const lunatic = difficultySettings[currentDiff].enemyDef || 1;   // v16: antes solo LUNÁTICO tenía bonus (LUNATIC_ENEMY_DEF_BONUS)
    const now = Date.now();
    const nPartners = (typeof partners !== 'undefined' && partners) ? partners.length : 0;
    const pu = (powerUps.doubleFire > now ? DEF_DOUBLEFIRE_ENEMY : 1) * (powerUps.superShot > now ? DEF_SUPERSHOT_ENEMY : 1);
    let f = (1 + levelDefenseStep() * DEF_PER_LEVEL_ENEMY) * (1 + (powerLevel - 1) * DEF_PER_ATTACK_ENEMY) * (1 + nPartners * DEF_PER_PARTNER_ENEMY) * pu * lunatic * lunaticEnemyBoost();
    const relief = LATE_LEVEL_DEF_MULT[currentDiff];
    if (relief) { const k = Math.max(0, Math.min(1, (currentLevelIndex() - (LATE_LEVEL_FROM - 2)) / 2)); if (k > 0) f = Math.max(1, f * (1 + (relief - 1) * k)); }   // v33: niveles 5-7 más llevaderos (rampa en los niveles 3-4)
    return f;   // +18 % de vida en Lunático
}
// v40: en LUNÁTICO los dos últimos jefes (Ojo Carmesí, nivel 7, y el Invasor) son más duros: sus balas y ataques NO se pueden
// romper (ni con bombas, ni con Omega, ni con rayos) y tienen algo más de defensa para poder ver sus ataques.
const FINAL_BOSS_DEF_MULT = 1.3;
function bossBulletsImmune() {
    try { return currentDiff === 'lunatico' && currentMode !== 'clasico' && !!activeBoss && activeBoss.state !== 'dead' && (activeBoss.levelIdx === 6 || activeBoss.levelIdx === 7); } catch (e) { return false; }
}
function bossDefenseFactor() {
    if (currentMode === 'clasico') return 1;
    return (bossBulletsImmune() ? FINAL_BOSS_DEF_MULT : 1) * (1 + levelDefenseStep() * DEF_PER_LEVEL_BOSS) * (1 + (powerLevel - 1) * DEF_PER_ATTACK_BOSS) * (difficultySettings[currentDiff].bossDef || 1);
}
// Multiplicador de la probabilidad de que caigan power-ups (Item): baja con el nivel y con tu poder.
function powerupDropMult() {
    if (currentMode === 'clasico') return 1;
    return Math.max(POWERUP_DROP_MIN, 1 - levelDefenseStep() * POWERUP_DROP_LOSS_PER_LEVEL - (powerLevel - 1) * POWERUP_DROP_LOSS_PER_ATTACK) * (difficultySettings[currentDiff].dropMult || 1);
}

// Progreso directo del Nivel de Ataque: se llama una vez por cada enemigo derrotado
// (n = cantidad de enemigos). Cuando se acumulan 65, sube el nivel y suena el jingle.
function addAttackProgress(n) {
    if (powerLevel >= MAX_POWER_LEVEL) return;
    enemiesDefeatedForPower += n;
    while (enemiesDefeatedForPower >= KILLS_PER_LEVEL && powerLevel < MAX_POWER_LEVEL) {
        enemiesDefeatedForPower -= KILLS_PER_LEVEL;
        powerLevel++;
        playLevelUpSound();
        levelUpFlash = 90;
    }
    if (powerLevel >= MAX_POWER_LEVEL) enemiesDefeatedForPower = 0;
}

let currentWave = 1;
let waveTimer = 0; 
// Cada nivel ahora se divide en dos oleadas de enemigos separadas por un mini
// jefe: OLEADA 1 -> MINI JEFE -> OLEADA 2 -> JEFE final. Cada duración es una
// mitad de la duración total de antes, para que el nivel no se sienta más largo.
const WAVE1_DURATION = 3000;   // v15: 50 s (60 fps)
const WAVE2_DURATION = 3000;   // v15: 50 s
// MODO MODERNO: cada oleada de enemigos dura 1 minuto (3600 frames a 60fps).
const MODERN_WAVE_DURATION = 3000;   // v15: 50 s
function waveDurFor() {
    if (currentMode === 'moderno') return MODERN_WAVE_DURATION;
    return levelPhase === 'wave1' ? WAVE1_DURATION : WAVE2_DURATION;
}
// Descenso más pausado de los enemigos en Moderno (las oleadas son más largas).
// Los enemigos bajan ~22 % más rápido que antes (ajusta ENEMY_DESCENT_BOOST: 1 = como antes).
const ENEMY_DESCENT_BOOST = 1.80;   // v31: antes 1.32 (+48 % de velocidad de descenso).    // antes 1.22: los enemigos bajan ~8 % más rápido en todas las dificultades
// Velocidad extra POR NIVEL: cada nivel suma este porcentaje al descenso (más alto cuanto mayor la dificultad).
// Se acumula hasta el nivel 10. Ej. Medio: nivel 1 = x1.00, nivel 4 = x1.105, nivel 6 = x1.175. Ajusta los valores a gusto.
const ENEMY_LEVEL_STEP = { facil: 0.035, medio: 0.05, dificil: 0.058, lunatico: 0.065 };   // v31: antes 0.025 / 0.035 / 0.045 / 0.05
function enemyLevelSpeed() { return 1 + (ENEMY_LEVEL_STEP[currentDiff] || 0.035) * (Math.min(Math.max(currentWave, 1), 10) - 1); }
function enemyDescentMult() { return (currentMode === 'moderno' ? 0.78 : 1) * ENEMY_DESCENT_BOOST * lunaticEnemyBoost() * enemyLevelSpeed(); }   // +18 % al bajar en Lunático
let activeBoss = null;
let isEndless = false;

// ==========================================
// FORMACIONES DE HADAS (filas de 5, estilo Touhou)
// ==========================================
// Cada cierto tiempo, en vez de (o además de) los enemigos sueltos de siempre,
// entra una fila completa de 5 enemigos coordinados, cada vez con un patrón de
// movimiento de grupo distinto (línea ondulante, V que se abre, serpiente con
// retraso, cruce de dos grupos, o espiral que se abre). Todas mantienen el
// mismo descenso vertical uniforme que cualquier enemigo normal; solo cambia
// el recorrido lateral, que es coordinado entre las 5 en vez de individual.
let formationCooldown = 220;
const FORMATION_PATTERNS = ['arc-drift', 'wedge', 'file', 'sweep', 'fan'];
// Formaciones RÍGIDAS: fila horizontal, columna y V perfectas. Todos los integrantes bajan lento, a la
// misma velocidad, con separación fija y el mismo balanceo (sin temblor propio), así no se deforman.
const RIGID_PATTERNS = ['row', 'column', 'vee'];

// ==========================================
// ENEMIGOS MENORES DURANTE EL MINI JEFE
// ==========================================
// Mientras el mini jefe está activo, además de él bajan hadas menores (1 golpe
// las derriba) que disparan una sola bala cada 0.8s y luego siguen bajando
// hasta salir de la pantalla. Dejan de aparecer en cuanto el mini jefe cae.
let miniBossMinionTimer = 0;
const MINIBOSS_MINION_INTERVAL = 180; // ~2.15s entre apariciones a 60fps

// ==========================================
// MINI JEFES (a mitad de cada nivel)
// ==========================================
// levelPhase recorre: 'wave1' -> 'miniboss' -> 'wave2' -> 'boss'
let levelPhase = 'wave1';
let activeMiniBoss = null;
let miniBossAnnounceTimer = 0;
