const POWERUP_NAMES = ['Escudo', 'Doble Disparo', 'Parálisis Enemiga', 'Disparo Súper'];

// CAMBIO 1: Temporizador de entrada del Jefe ampliado para ser más épico y lento
let bossIntroTimer = 0;
