// CAMBIO 3: Temporizador para la animación de inicio "Épica"
let gameStartTimer = 0;
const GAME_START_DURATION = 180;
let introPixels = [];

// bulletDensity: multiplica la CANTIDAD de balas por disparo/abanico (menos balas en fácil).
// bulletIntervalMult: multiplica el tiempo entre disparos (más espera = menos balas por segundo en fácil).
// LUNÁTICO · últimos niveles: 0 en cualquier otro caso; 1, 2 y 3 en los niveles 5, 6 y 7.
// Se usa para meter más enemigos, más enemigos con función (BLASTER/PULSER/SNIPER/BOMBER) y formaciones más grandes.
function lunaticLate() {
    if (currentDiff !== 'lunatico' || currentMode === 'clasico') return 0;
    return Math.max(0, Math.min(3, (currentLevelIndex() + 1) - 4));
}
let difficultySettings = {
    // v16: las 4 dificultades se notan MUCHO más entre sí, pero siguen siendo justas:
    //  - FÁCIL es más suave (balas lentas y pocas, más avisos, más poderes y más tiempo de invulnerabilidad).
    //  - MEDIO es la referencia.
    //  - DIFÍCIL y LUNÁTICO suben velocidad de balas y enemigos, densidad de patrones, vida de enemigos/jefes
    //    y frecuencia de habilidades, pero con tope de balas en pantalla y avisos que nunca desaparecen.
    // enemyDef / bossDef: multiplican la resistencia (el daño que recibes se divide por este valor).
    // dropMult: multiplica la probabilidad de que caigan power-ups. invulMs: invulnerabilidad tras recibir un golpe.
    facil:    { spawnRate: 0.009, enemySpawnRate: 0.0055, maxEnemies: 7,  bulletSpeed: 2.6, enemySpeedMult: 0.72, bulletDensity: 0.26, bulletIntervalMult: 2.8,  maxEnemyBullets: 34,  enemyDef: 1.00, bossDef: 0.80, dropMult: 1.35, invulMs: 2600 },
    medio:    { spawnRate: 0.017, enemySpawnRate: 0.0085, maxEnemies: 9,  bulletSpeed: 4.0, enemySpeedMult: 1.0,  bulletDensity: 0.42, bulletIntervalMult: 1.95, maxEnemyBullets: 52,  enemyDef: 1.30, bossDef: 1.00, dropMult: 1.0,  invulMs: 2000 },
    dificil:  { spawnRate: 0.030, enemySpawnRate: 0.012,  maxEnemies: 11, bulletSpeed: 5.5, enemySpeedMult: 1.35, bulletDensity: 0.60, bulletIntervalMult: 1.5,  maxEnemyBullets: 72,  enemyDef: 1.70, bossDef: 1.20, dropMult: 0.9,  invulMs: 1800 },
    // LUNÁTICO: el más rápido, denso y resistente; aun así con tope de balas para que sea justo.
    lunatico: { spawnRate: 0.042, enemySpawnRate: 0.016,  maxEnemies: 13, bulletSpeed: 6.8, enemySpeedMult: 1.65, bulletDensity: 0.78, bulletIntervalMult: 1.15, maxEnemyBullets: 95,  enemyDef: 2.20, bossDef: 1.40, dropMult: 0.8,  invulMs: 1600 }
};
let currentDiff = 'medio';

// Tope de balas enemigas simultáneas en pantalla según la dificultad (evita el "muro" de balas).
// bossFiring lo activan Boss.update / MiniBoss.update (criaturas.js) mientras el jefe dispara.
let bossFiring = false;
function pushEnemyBullet(b) {
    // Una bala con posición o velocidad NaN nunca sale de pantalla (todas las comparaciones dan false):
    // se quedaba para siempre en la lista, llenaba el tope y dejaba al jefe sin balas. Nunca entra.
    if (!b || !isFinite(b.x) || !isFinite(b.y) || !isFinite(b.vx) || !isFinite(b.vy)) return;
    const cap = difficultySettings[currentDiff].maxEnemyBullets || 100;
    if (bossFiring) {
        // Las balas de jefes y mini jefes tienen prioridad: cupo propio (mayor) y, si se llena,
        // se retira la bala más vieja de las hadas en vez de cortar el patrón del jefe a la mitad.
        b.fromBoss = true;
        const hard = Math.round(cap * 2.6);
        if (enemyBullets.length >= hard) {
            let idx = enemyBullets.findIndex(o => !o.fromBoss);
            enemyBullets.splice(idx < 0 ? 0 : idx, 1);
        }
        enemyBullets.push(b);
        return;
    }
    // Las balas de las hadas se cuentan aparte: las del jefe ya no les quitan cupo (ni al revés).
    let n = 0;
    for (let i = 0; i < enemyBullets.length; i++) if (!enemyBullets[i].fromBoss) n++;
    if (n >= cap) return;
    enemyBullets.push(b);
}



// ==========================================
// BARRA DE VIDA DE JEFES / MINI JEFES (estilo Dragon Ball Z: Budokai Tenkaichi 3)
// ==========================================
// Marco dorado inclinado, retrato circular con el color del nivel, placa con el nombre, barra con brillo
// que pasa de amarillo a naranja y rojo según la vida, estela blanca/roja del daño reciente y marcas
// en 25/50/75 % (la de 50 % es donde el jefe lanza su ataque especial).
function drawBossHealthBar(boss, isMini, name) {
    if (!boss || !boss.maxHp) return;
    const maxHp = boss.maxHp, hp = Math.max(0, boss.hp);
    const ratio = Math.min(1, hp / maxHp);
    // Estado de animación guardado en el propio jefe
    if (boss._bt3 === undefined) boss._bt3 = { trail: ratio, last: ratio, hold: 0, flash: 0, pulse: 0, born: 0 };
    const A = boss._bt3;
    A.born++;
    if (ratio < A.last - 0.0005) { A.hold = 28; A.flash = 7; }           // recibió daño: la estela espera y luego baja
    A.last = ratio;
    if (A.hold > 0) A.hold--; else if (A.trail > ratio) A.trail = Math.max(ratio, A.trail - 0.0045);
    if (A.trail < ratio) A.trail = ratio;
    if (A.flash > 0) A.flash--;
    A.pulse++;

    const accent = (typeof LEVEL_THEMES !== 'undefined' && LEVEL_THEMES[boss.levelIdx]) ? LEVEL_THEMES[boss.levelIdx].accent : '#ffcf5c';
    const slide = Math.min(1, A.born / 26), ease = 1 - Math.pow(1 - slide, 3);   // entra deslizando desde arriba
    const sc = isMini ? 0.78 : 1;
    const barH = Math.round(16 * sc), skew = Math.round(10 * sc), portR = Math.round(19 * sc);
    const totalW = isMini ? Math.min(330, playAreaW * 0.8) : Math.min(playAreaW - 20, 560);
    const x0 = Math.round(playAreaW / 2 - totalW / 2);
    const y0 = Math.round((isMini ? 26 : 8) - (1 - ease) * 60);
    const bx = x0 + portR * 2 + 4, bw = totalW - (portR * 2 + 4);   // zona de la barra (a la derecha del retrato)
    const by = y0 + Math.round(6 * sc);

    const para = (x, y, w, h, s) => { ctx.beginPath(); ctx.moveTo(x + s, y); ctx.lineTo(x + w, y); ctx.lineTo(x + w - s, y + h); ctx.lineTo(x, y + h); ctx.closePath(); };
    ctx.save();
    ctx.globalAlpha = Math.min(1, ease * 1.4);

    // Placa del nombre (arriba, inclinada)
    const label = name || (isMini ? 'MINI JEFE' : 'JEFE');
    ctx.font = Math.round(9 * sc + 1) + 'px "Press Start 2P"';
    const nameW = Math.min(bw - 30, ctx.measureText(label).width + 26);
    ctx.fillStyle = 'rgba(8,6,16,0.88)'; para(bx + 6, y0 - 1, nameW, Math.round(12 * sc), 7); ctx.fill();
    ctx.strokeStyle = '#d9a520'; ctx.lineWidth = 1.5; para(bx + 6, y0 - 1, nameW, Math.round(12 * sc), 7); ctx.stroke();
    ctx.fillStyle = '#fff3b0'; ctx.shadowColor = '#000'; ctx.shadowBlur = 3; ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
    ctx.fillText(label, bx + 18, y0 + Math.round(5 * sc)); ctx.shadowBlur = 0;

    // Marco exterior de la barra: oscuro con borde dorado en degradado
    ctx.fillStyle = '#07060c'; para(bx - 3, by - 3, bw + 6, barH + 6, skew + 2); ctx.fill();
    const gold = ctx.createLinearGradient(0, by - 3, 0, by + barH + 3);
    gold.addColorStop(0, '#fff2a8'); gold.addColorStop(0.45, '#e0a81c'); gold.addColorStop(1, '#6b4600');
    ctx.strokeStyle = gold; ctx.lineWidth = 2.5; para(bx - 3, by - 3, bw + 6, barH + 6, skew + 2); ctx.stroke();

    // Fondo vacío de la barra
    ctx.fillStyle = '#2a1a1a'; para(bx, by, bw, barH, skew); ctx.fill();

    // Recorte con la forma de la barra para rellenarla
    ctx.save(); para(bx, by, bw, barH, skew); ctx.clip();
    const wFull = bw, wHp = wFull * ratio, wTrail = wFull * A.trail;
    // Estela de daño: blanca al principio, roja después
    if (wTrail > wHp) {
        ctx.fillStyle = A.hold > 0 ? '#ffffff' : '#e02020';
        ctx.fillRect(bx + wHp, by, wTrail - wHp + skew, barH);
    }
    // Relleno de vida: amarillo → naranja → rojo
    let c1, c2;
    if (ratio > 0.5)       { c1 = '#fff98a'; c2 = '#ffb400'; }
    else if (ratio > 0.25) { c1 = '#ffd27a'; c2 = '#ff6d00'; }
    else                   { c1 = '#ff8a7a'; c2 = '#c40000'; }
    const hg = ctx.createLinearGradient(0, by, 0, by + barH);
    hg.addColorStop(0, c1); hg.addColorStop(1, c2);
    ctx.fillStyle = hg; ctx.fillRect(bx, by, wHp + (ratio > 0 ? skew : 0), barH);
    // Brillo superior
    ctx.fillStyle = 'rgba(255,255,255,0.38)'; ctx.fillRect(bx, by + 1, wHp + skew, Math.max(2, Math.round(barH * 0.32)));
    // Destello al recibir un golpe
    if (A.flash > 0) { ctx.fillStyle = 'rgba(255,255,255,' + (A.flash / 7 * 0.55) + ')'; ctx.fillRect(bx, by, wHp + skew, barH); }
    // Barrido de luz que recorre la barra
    const sweep = ((A.pulse % 150) / 150) * (wHp + 60) - 30;
    const sg = ctx.createLinearGradient(bx + sweep - 22, 0, bx + sweep + 22, 0);
    sg.addColorStop(0, 'rgba(255,255,255,0)'); sg.addColorStop(0.5, 'rgba(255,255,255,0.35)'); sg.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = sg; ctx.fillRect(bx, by, wHp + skew, barH);
    // Parpadeo rojo cuando queda poca vida
    if (ratio <= 0.25 && ratio > 0) { ctx.fillStyle = 'rgba(255,0,0,' + (0.12 + 0.12 * Math.sin(A.pulse * 0.25)) + ')'; ctx.fillRect(bx, by, wFull, barH); }
    // Marcas de 25/50/75 % (la de 50 % más gruesa: ataque especial)
    [0.25, 0.5, 0.75].forEach(f => {
        ctx.fillStyle = f === 0.5 ? 'rgba(0,0,0,0.75)' : 'rgba(0,0,0,0.45)';
        ctx.fillRect(Math.round(bx + wFull * f) - (f === 0.5 ? 1 : 0), by, f === 0.5 ? 3 : 2, barH);
    });
    ctx.restore();

    // Filo claro inferior de la barra
    ctx.strokeStyle = 'rgba(255,255,255,0.25)'; ctx.lineWidth = 1; para(bx, by, bw, barH, skew); ctx.stroke();

    // Retrato circular (color del nivel) con anillo dorado y emblema
    const px0 = x0 + portR, py0 = by + barH / 2;
    const ring = ctx.createLinearGradient(0, py0 - portR, 0, py0 + portR);
    ring.addColorStop(0, '#fff2a8'); ring.addColorStop(0.5, '#d9a520'); ring.addColorStop(1, '#6b4600');
    ctx.fillStyle = '#07060c'; ctx.beginPath(); ctx.arc(px0, py0, portR + 2, 0, Math.PI * 2); ctx.fill();
    const pg = ctx.createRadialGradient(px0 - portR * 0.3, py0 - portR * 0.3, 2, px0, py0, portR);
    pg.addColorStop(0, '#ffffff'); pg.addColorStop(0.35, accent); pg.addColorStop(1, '#10101c');
    ctx.fillStyle = pg; ctx.beginPath(); ctx.arc(px0, py0, portR - 1, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = ring; ctx.lineWidth = 3; ctx.beginPath(); ctx.arc(px0, py0, portR, 0, Math.PI * 2); ctx.stroke();
    // Emblema: estrella de 4 puntas (jefe) o rombo (mini jefe)
    ctx.fillStyle = 'rgba(10,8,20,0.8)'; ctx.beginPath();
    const er = portR * (isMini ? 0.5 : 0.62);
    if (isMini) { ctx.moveTo(px0, py0 - er); ctx.lineTo(px0 + er, py0); ctx.lineTo(px0, py0 + er); ctx.lineTo(px0 - er, py0); }
    else { for (let i = 0; i < 8; i++) { const a = -Math.PI / 2 + i * Math.PI / 4, r = i % 2 ? er * 0.32 : er; ctx.lineTo(px0 + Math.cos(a) * r, py0 + Math.sin(a) * r); } }
    ctx.closePath(); ctx.fill();
    // Porcentaje en el borde derecho
    ctx.font = Math.round(7 * sc + 1) + 'px "Press Start 2P"'; ctx.textAlign = 'right'; ctx.textBaseline = 'middle';
    ctx.fillStyle = '#fff'; ctx.shadowColor = '#000'; ctx.shadowBlur = 3;
    ctx.fillText(Math.ceil(ratio * 100) + '%', bx + bw - skew - 2, y0 + Math.round(5 * sc)); ctx.shadowBlur = 0;
    ctx.restore();
    ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
}
const BOSS_BAR_NAMES = ['Kyūbi, Zorro de Nueve Colas', 'Rey Yeti de la Ventisca', 'Kraken Espectral', 'Reina Araña', 'Archiliche Bibliotecario', 'Coloso del Reloj', 'Ojo Gigante'];

// Cantidad de niveles activos en la campaña según la dificultad: LUNÁTICO añade
// la Fase 7 exclusiva ("Luna Sangrante") al final de los 6 niveles normales.
function activeLevelCount() { return currentDiff === 'lunatico' ? 7 : 6; }
// Cierto solo en el instante exacto en que se está peleando/venciendo al jefe de esa Fase 7.
function isLunaticFinalLevel() { return currentMode === 'moderno' && currentDiff === 'lunatico' && currentWave === 7; }

function createBunkers() {
    bunkers = [];
    let centers = [0.2, 0.4, 0.6, 0.8].map(f => playAreaW * f);
    let by = playAreaH - 140; 
    for (let cx of centers) {
        let startX = cx - 30; 
        for(let row=0; row<5; row++) {
            for(let col=0; col<6; col++) {
                if (row === 0 && (col === 0 || col === 5)) continue; 
                if (row > 2 && (col === 2 || col === 3)) continue; 
                bunkers.push({x: startX + col*10, y: by + row*10, w: 10, h: 10});
            }
        }
    }
}

function createClassicEnemies() {
    classicEnemies = [];
    classicEnemyDir = 1;
    let colSpacing = Math.max(35, playAreaW * 0.06);
    let startX = playAreaW * 0.15;
    let startY = 80 + ((currentWave - 1) * 20); 
    for(let r=0; r<5; r++) {
        for(let c=0; c<11; c++) {
            let type = (r === 0) ? 3 : (r < 3 ? 2 : 1);
            let color = type === 3 ? '#ff0' : (type === 2 ? '#a52' : '#f55');
            classicEnemies.push({
                x: startX + c * colSpacing, y: startY + r * 40, width: 30, height: 25, type: type, color: color,
                draw() { drawPixelInvader(this.x, this.y, this.width / 11, this.color); }
            });
        }
    }
}

class Planet {
    constructor() {
        this.x = Math.random() * playAreaW;
        this.y = Math.random() * playAreaH;
        this.radius = Math.random() * 60 + 40;
        this.vy = Math.random() * 0.15 + 0.05;
        let r = Math.floor(Math.random() * 100 + 50);
        let g = Math.floor(Math.random() * 100 + 50);
        let b = Math.floor(Math.random() * 150 + 100);
        this.color = `rgba(${r}, ${g}, ${b}, 0.12)`;
        this.spots = [];
        for(let i=0; i<20; i++){
            this.spots.push({
                ox: (Math.random() - 0.5) * this.radius * 1.4,
                oy: (Math.random() - 0.5) * this.radius * 1.4,
                s: Math.random() * 12 + 4
            });
        }
    }
    update() {
        this.y += this.vy;
        if(this.y - this.radius > playAreaH) {
            this.y = -this.radius;
            this.x = Math.random() * playAreaW;
        }
    }
    draw() {
        ctx.fillStyle = this.color;
        ctx.beginPath(); ctx.arc(this.x, this.y, this.radius, 0, Math.PI*2); ctx.fill();
        ctx.fillStyle = 'rgba(0,0,0,0.15)';
        this.spots.forEach(sp => {
            let dx = this.x + sp.ox; let dy = this.y + sp.oy;
            let dist = Math.sqrt(sp.ox*sp.ox + sp.oy*sp.oy);
            if (dist < this.radius - sp.s) { ctx.fillRect(dx, dy, sp.s, sp.s); }
        });
    }
}

// Durante la bajada del jefe, el fondo se va tiñendo de rojo poco a poco y empieza
// a parpadear como una alarma que se activa, hasta un destello final cuando llega a su posición.
function drawBossAlertOverlay(boss) {
    if (boss.state === 'intro' && typeof Cine !== 'undefined') { Cine.drawBossBack(boss); return; }   // escena propia de cada jefe
    if (boss.state === 'intro') {
        let progress = Math.max(0, Math.min(1, (boss.y + 170) / 220));
        let flashSpeed = 0.05 + progress * 0.25;
        let flash = (Math.sin(boss.timer * flashSpeed) + 1) / 2;
        let baseAlpha = progress * 0.5;
        let alpha = baseAlpha * (0.6 + flash * 0.4);

        ctx.fillStyle = `rgba(180, 0, 0, ${alpha.toFixed(3)})`;
        ctx.fillRect(0, 0, playAreaW, playAreaH);

        // La viñeta con degradado radial es puramente decorativa y solo dura
        // los ~7s de la entrada del jefe; se omite en Modo Rendimiento.
        if (!performanceMode) {
            let vig = ctx.createRadialGradient(
                playAreaW / 2, playAreaH / 2, playAreaH * (0.95 - progress * 0.5),
                playAreaW / 2, playAreaH / 2, playAreaH * 0.95
            );
            vig.addColorStop(0, 'rgba(150,0,0,0)');
            vig.addColorStop(1, `rgba(150,0,0,${((0.35 + flash * 0.25) * progress).toFixed(3)})`);
            ctx.fillStyle = vig;
            ctx.fillRect(0, 0, playAreaW, playAreaH);
        }

        if (progress > 0.75 && flash > 0.92) {
            ctx.fillStyle = `rgba(255,255,255,${((flash - 0.92) * 3).toFixed(3)})`;
            ctx.fillRect(0, 0, playAreaW, playAreaH);
        }
    } else {
        ctx.fillStyle = 'rgba(40, 0, 0, 0.25)';
        ctx.fillRect(0, 0, playAreaW, playAreaH);
    }
}

function drawBossBgPlanet() {
    if (!bossBgPlanet) return;
    bossBgPlanet.pulse += 0.02;
    let pulseFactor = 1 + Math.sin(bossBgPlanet.pulse) * 0.04;
    let r = bossBgPlanet.radius * pulseFactor;
    // El degradado radial se recalcula cada frame y es notablemente caro en
    // equipos flojos; en Modo Rendimiento se sustituye por un relleno plano.
    if (performanceMode) {
        ctx.fillStyle = 'rgba(150, 20, 20, 0.22)';
        ctx.beginPath(); ctx.arc(bossBgPlanet.x, bossBgPlanet.y, r, 0, Math.PI * 2); ctx.fill();
        return;
    }
    let gradient = ctx.createRadialGradient(bossBgPlanet.x, bossBgPlanet.y, r * 0.08, bossBgPlanet.x, bossBgPlanet.y, r);
    gradient.addColorStop(0, 'rgba(255, 70, 30, 0.55)');
    gradient.addColorStop(0.5, 'rgba(180, 20, 20, 0.30)');
    gradient.addColorStop(1, 'rgba(120, 0, 0, 0)');
    ctx.fillStyle = gradient;
    ctx.beginPath(); ctx.arc(bossBgPlanet.x, bossBgPlanet.y, r, 0, Math.PI * 2); ctx.fill();
}

