            if (!sfxBus) { sfxBus = audioCtx.createGain(); sfxBus.gain.value = 0.26; sfxBus.connect(audioCtx.destination); }
            if (!noiseBuf) {
                noiseBuf = audioCtx.createBuffer(1, Math.floor(audioCtx.sampleRate * 0.8), audioCtx.sampleRate);
                const d = noiseBuf.getChannelData(0); for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
            }
