// ----------------------------------------------------------- cerebro: alterna ataque base y habilidades
function restFrames(b, phase, special, isMini) {
    const m = difficultySettings[currentDiff].bulletIntervalMult || 1;
    return Math.round((isMini ? 115 : (special ? 65 : [145, 115, 90][phase - 1])) * m * (b.defenseMode ? 0.7 : 1));   // menos espera: el jefe usa sus habilidades más seguido
}
function runBrain(b, pool, phase, special, base, speed) {
    const isMini = b instanceof MiniBoss;
    if (b._ab) {
        const a = b._ab; a.t++;
        b._abShow = a.t < WIND + 75;
        if (a.t > WIND) a.d.tick(b, mkH(b, speed), a.t - WIND, phase);
        if (a.t >= WIND + a.d.dur) { b._ab = null; b._alpha = 1; b._cd = restFrames(b, phase, special, isMini); b._abShow = false; }
        return;
    }
    if (b._cd === undefined) b._cd = special ? 40 : 120;
    if (--b._cd <= 0) {
        const cand = pool.filter(d => d.minPhase <= phase && (!d.sp || special) && d !== b._last);
        let pick = cand;
        if (b.defenseMode && rnd() < 0.7) { const strong = cand.filter(x => x.sp || x.minPhase >= phase); if (strong.length) pick = strong; }   // MODO DEFENSA: prefiere las habilidades más poderosas
        const d = pick.length ? pick[Math.floor(rnd() * pick.length)] : null;
        if (d) { b._last = d; b._ab = { d, t: 0 }; b._abName = d.name; b._abShow = true; blip(d.sp ? 380 : 560); } else b._cd = 60;
    }
    base();
}

// ----------------------------------------------------------- JEFE FINAL (1-6): dibujo + ataques
// Pose de ataque para el motor pixel art: carga (aplastarse y temblar) → lanzamiento (pulso y chispas)
function pxPose(b) {
    const ab = b._ab;
    if (b.state === 'specialTelegraph') {
        const tf = b instanceof MiniBoss ? TELEGRAPH_FRAMES_MINI : TELEGRAPH_FRAMES_BOSS;
        return { name: 'charge', p: Math.max(0, Math.min(1, (b.telegraphTimer || 0) / tf)) };
    }
    if (ab) return ab.t <= WIND ? { name: 'charge', p: ab.t / WIND } : { name: 'cast', t: ab.t - WIND };
    return null;
}
const bDraw = Boss.prototype.draw, bUpdate = Boss.prototype.update, bSpell = Boss.prototype.runSpellCard, bSpec = Boss.prototype.runSpecialAttack;
function abilityFx(b, accent, isMini) {
    const ab = b._ab, cx = b.x + b.width / 2, cy = b.y + b.height / 2;
    if (ab && ab.t <= WIND) {                       // carga: anillo que se cierra + brillo
        const p = ab.t / WIND;
        PX.ring(ctx, cx, cy, b.width * (1.0 - 0.45 * p), accent, 0.35 + 0.55 * p, 4);
    }
    if (b._abShow && b._abName) {                   // rótulo con el nombre de la habilidad
        const a = b._ab ? b._ab.t : 0, fade = Math.min(1, a / 8) * Math.min(1, (WIND + 75 - a) / 12);
        ctx.save(); ctx.globalAlpha = Math.max(0, fade); ctx.textAlign = 'center';
        ctx.font = (isMini ? '10px' : '11px') + ' "Press Start 2P"';
        const w = ctx.measureText(b._abName).width + 26, y = isMini ? 62 : 52;
        ctx.fillStyle = 'rgba(10,0,10,0.7)'; ctx.fillRect(playAreaW / 2 - w / 2, y, w, 22);
        ctx.strokeStyle = accent; ctx.lineWidth = 2; ctx.strokeRect(playAreaW / 2 - w / 2, y, w, 22);
        ctx.fillStyle = '#fff'; ctx.fillText(b._abName, playAreaW / 2, y + 15);
        ctx.restore();
    }
}
function glowCircle(x, y, r, col, a) {
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, col); g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = a; ctx.fillStyle = g; ctx.fillRect(x - r, y - r, r * 2, r * 2);
    ctx.globalCompositeOperation = 'source-over';
}
Boss.prototype.draw = function (frame) {
    if (this.levelIdx === 6) return bDraw.call(this, frame);          // ojo gigante: intacto
    if (this.state === 'dead') return;
    if (typeof Cine !== 'undefined' && Cine.bossHidden(this)) return;   // aún no aparece en su presentación
    drawBossAura(this);
    const cx = this.x + this.width / 2, cy = this.y + this.height / 2, accent = LEVEL_THEMES[this.levelIdx].accent;
    ctx.save();
    if (this.state === 'intro' && typeof Cine !== 'undefined') Cine.bossTransform(this);   // pose de la presentación
    if (this._alpha !== undefined && this._alpha < 1) ctx.globalAlpha = Math.max(0, this._alpha);
    ctx.translate(cx, cy);
    PX.draw(ctx, this, BOSS[this.levelIdx], { kind: 'boss', boxW: this.width, cx, cy, t: this.timer, rest: [this], accent, pose: pxPose(this) });
    ctx.restore();
    abilityFx(this, accent, false);
    if (this.state === 'specialTelegraph') {
        drawSpecialAttackTelegraph(this, BOSS_SPECIAL_NAMES[this.levelIdx], Math.max(0, Math.min(1, this.telegraphTimer / TELEGRAPH_FRAMES_BOSS)), false);
    } else if (this.specialActive) {
        const pulse = (S(this.timer * 0.25) + 1) / 2;
        ctx.save(); ctx.globalAlpha = 0.25 + pulse * 0.2; ctx.strokeStyle = '#fff200'; ctx.lineWidth = 4;
        ctx.strokeRect(this.x - 6, this.y - 6, this.width + 12, this.height + 12); ctx.restore();
    }
    if (this.defenseMode && this.specialActive) {   // MODO DEFENSA (Lunático): aura azul
        const pu = (S(this.timer * 0.15) + 1) / 2;
        ctx.save(); ctx.globalAlpha = 0.3 + pu * 0.25; ctx.strokeStyle = '#6cc4ff'; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.arc(this.x + this.width / 2, this.y + this.height / 2, Math.max(this.width, this.height) * 0.62, 0, Math.PI * 2); ctx.stroke(); ctx.restore();
    }
    drawBossHealthBar(this, false, BOSS_BAR_NAMES[this.levelIdx]);
};
Boss.prototype.update = function () {
    bossFiring = true;                       // sus balas tienen cupo propio (ver pushEnemyBullet)
    try {
        bUpdate.call(this);
        if (this.levelIdx === 6) return;
        if (this.state === 'specialTelegraph') { this._alpha = 1; this._ab = null; this._abShow = false; this._cd = 70; }
        serveSummons(this);
    } finally { bossFiring = false; }
};
Boss.prototype.runSpellCard = function (phase, speed, cx, cy, ang) {
    if (this.levelIdx === 6) return bSpell.call(this, phase, speed, cx, cy, ang);
    runBrain(this, BOSS_AB[this.levelIdx], phase, false, () => bSpell.call(this, phase, speed, cx, cy, ang), speed);
};
Boss.prototype.runSpecialAttack = function (speed, cx, cy, ang) {
    if (this.levelIdx === 6) return bSpec.call(this, speed, cx, cy, ang);
    runBrain(this, BOSS_AB[this.levelIdx], 3, true, () => bSpec.call(this, speed, cx, cy, ang), speed);
};
// Los enemigos que invoca el jefe (la pelea normal no los actualiza, así que lo hacemos aquí)
function serveSummons(b) {
    if (typeof enemies === 'undefined') return;
    for (let i = enemies.length - 1; i >= 0; i--) {
        const e = enemies[i]; if (!e._sum) continue;
        if (b.state === 'dead') { enemies.splice(i, 1); continue; }
        e.update(); e.draw(currentEnemyFrame); e.maybeShoot();
        if (Date.now() > invulnerableUntil && player.x < e.x + e.width && player.x + player.width > e.x && player.y < e.y + e.height && player.y + player.height > e.y) {
            createExplosion(player.x + player.width / 2, player.y + player.height / 2, player.color, 30);
            lives--; invulnerableUntil = Date.now() + (difficultySettings[currentDiff].invulMs || 2000);
            powerLevel = Math.max(1, Math.floor(powerLevel / 2)); enemiesDefeatedForPower = 0; powerPoints = Math.max(0, powerPoints - 50);
            e.hp = 0; createExplosion(e.x + e.width / 2, e.y + e.height / 2, e.color, 80); enemies.splice(i, 1);
            if (lives <= 0) gameOver();
            continue;
        }
        if (e.y > playAreaH) enemies.splice(i, 1);
    }
}

// ----------------------------------------------------------- MINI JEFE (1-7): dibujo + ataques
const mDraw = MiniBoss.prototype.draw, mUpdate = MiniBoss.prototype.update, mAtk = MiniBoss.prototype.runAttack, mSpec = MiniBoss.prototype.runSpecialAttack;
MiniBoss.prototype.draw = function (frame) {
    if (this.state === 'dead') return;
    drawBossAura(this);
    const cx = this.x + this.width / 2, cy = this.y + this.height / 2, accent = LEVEL_THEMES[this.levelIdx].accent;
    ctx.save();
    if (this.levelIdx === 4 && this.state === 'intro') ctx.globalAlpha = (Math.floor(this.timer / 6) % 2 === 0) ? 1 : 0.25;
    if (this.levelIdx === 5 && this.state === 'intro') { ctx.translate(cx, cy); ctx.rotate(this.spin || 0); ctx.translate(-cx, -cy); }
    if (this._alpha !== undefined && this._alpha < 1) ctx.globalAlpha = Math.min(ctx.globalAlpha, Math.max(0, this._alpha));
    ctx.translate(cx, cy);
    PX.draw(ctx, this, MINI[this.levelIdx], { kind: 'mini', boxW: this.width, cx, cy, t: this.timer, rest: [this], accent, pose: pxPose(this) });
    ctx.restore();
    abilityFx(this, accent, true);
    if (this.state === 'specialTelegraph') {
        drawSpecialAttackTelegraph(this, MINIBOSS_SPECIAL_NAMES[this.levelIdx], Math.max(0, Math.min(1, this.telegraphTimer / TELEGRAPH_FRAMES_MINI)), true);
    } else if (this.specialActive) {
        const pulse = (S(this.timer * 0.25) + 1) / 2;
        ctx.save(); ctx.globalAlpha = 0.25 + pulse * 0.2; ctx.strokeStyle = '#fff200'; ctx.lineWidth = 3;
        ctx.strokeRect(this.x - 5, this.y - 5, this.width + 10, this.height + 10); ctx.restore();
    }
    if (this.defenseMode && this.specialActive) {   // MODO DEFENSA (Lunático): aura azul
        const pu = (S(this.timer * 0.15) + 1) / 2;
        ctx.save(); ctx.globalAlpha = 0.3 + pu * 0.25; ctx.strokeStyle = '#6cc4ff'; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.arc(this.x + this.width / 2, this.y + this.height / 2, Math.max(this.width, this.height) * 0.62, 0, Math.PI * 2); ctx.stroke(); ctx.restore();
    }
    drawBossHealthBar(this, true, MINIBOSS_NAMES[this.levelIdx] || 'MINI JEFE');
};
MiniBoss.prototype.update = function () {
    bossFiring = true;
    try {
        mUpdate.call(this);
        if (this.state === 'specialTelegraph') { this._alpha = 1; this._ab = null; this._abShow = false; this._cd = 60; }
    } finally { bossFiring = false; }
};
MiniBoss.prototype.runAttack = function (speed, cx, cy, ang) {
    runBrain(this, MINI_AB[this.levelIdx], 1, false, () => mAtk.call(this, speed, cx, cy, ang), speed);
};
MiniBoss.prototype.runSpecialAttack = function (speed, cx, cy, ang) {
    runBrain(this, MINI_AB[this.levelIdx], 1, true, () => mSpec.call(this, speed, cx, cy, ang), speed);
};

