// ============================================================================
//  FONDOS RETRO SIMÉTRICOS (7 niveles)
//  Cada nivel se pinta UNA vez en baja resolución (mitad izquierda) y se espeja;
//  después solo se desplaza en pasos de píxel (3 capas con parallax). Paleta corta, sin degradados.
// ============================================================================
function rng(a) { return function () { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
function mkc(w, h) { const c = document.createElement('canvas'); c.width = w; c.height = h; const g = c.getContext('2d'); g.imageSmoothingEnabled = false; return [c, g]; }
function disc(g, cx, cy, r, col) { g.fillStyle = col; for (let y = -r; y <= r; y++) { const w = Math.floor(Math.sqrt(r * r - y * y + 0.5)); g.fillRect(cx - w, cy + y, 2 * w + 1, 1); } }
function dpatch(g, cx, cy, rx, ry, col, al) { g.globalAlpha = al; g.fillStyle = col; for (let y = -ry; y <= ry; y++) for (let x = -rx; x <= rx; x++) if ((x * x) / (rx * rx) + (y * y) / (ry * ry) <= 1 && ((x + y) & 1) === 0) g.fillRect(cx + x, cy + y, 1, 1); g.globalAlpha = 1; }
function speck(g, R, n, cols, x0, x1, TH, sz) { for (let i = 0; i < n; i++) { g.fillStyle = cols[(R() * cols.length) | 0]; g.fillRect(x0 + ((R() * (x1 - x0)) | 0), (R() * TH) | 0, sz || 1, sz || 1); } }
function wrapY(TH, y, fn) { fn(y - TH); fn(y); fn(y + TH); }
function patt(g, rows, x, y, s, col) { rows.forEach((r, j) => { for (let i = 0; i < r.length; i++) if (r[i] === '#') { g.fillStyle = col; g.fillRect(x + i * s, y + j * s, s, s); } }); }
const SQUID = ['...##...', '..####..', '.######.', '##.##.##', '########', '..#..#..', '.#.##.#.', '#.#..#.#'];
const CRAB = ['..#.....#..', '...#...#...', '..#######..', '.##.###.##.', '###########', '#.#######.#', '#.#.....#.#', '...##.##...'];
function gearPix(g, cx, cy, r, teeth, ph, body, tooth, hub) {
    for (let k = 0; k < teeth; k++) { const a = ph + k * TAU / teeth; g.fillStyle = tooth; g.fillRect(Math.round(cx + Math.cos(a) * (r + 2)) - 1, Math.round(cy + Math.sin(a) * (r + 2)) - 1, 3, 3); }
    disc(g, cx, cy, r, body); disc(g, cx, cy, Math.max(2, Math.round(r * 0.4)), hub);
    g.fillStyle = tooth; for (let k = 0; k < 4; k++) { const a = ph + k * Math.PI / 2; for (let d = 2; d < r; d++) g.fillRect(Math.round(cx + Math.cos(a) * d), Math.round(cy + Math.sin(a) * d), 1, 1); }
}

