            const b = new Bullet(cx + (i - (n - 1) / 2) * 9 - 3, top - 8, false, false, 0, -22, 'player', 'mlaser');
            b.width = 6; b.height = 36; b.pierce = true; b.hitList = []; b.dmgMult = 0.7; b.drawFn = drawMLaser;   /* v39: 0.5 → 0.7 */ b.color = '#c9a0ff';
