                m.width = 6; m.height = 10; m.homing = true; m.homingSpeed = 8.2; m.homingTurnRate = 0.09; m.dmgMult = 0.85; m.drawFn = drawMMissile;   /* v39: 0.6 → 0.85 */ bullets.push(m);
