            ctx.fillStyle = '#fcfcfc'; poly([[0, h * 0.02], [w * 0.15, h * 0.36], [-w * 0.15, h * 0.36]]);                      // delantal
            ctx.fillStyle = '#fcd0a8'; ctx.beginPath(); ctx.arc(0, -h * 0.2, h * 0.11, 0, Math.PI * 2); ctx.fill();            // cara
            ctx.fillStyle = '#3a6cf0'; ctx.fillRect(-w * 0.07, -h * 0.21, w * 0.04, h * 0.04); ctx.fillRect(w * 0.03, -h * 0.21, w * 0.04, h * 0.04);
            ctx.fillStyle = '#2a1f3d'; ctx.beginPath(); ctx.ellipse(0, -h * 0.3, w * 0.36, h * 0.07, 0, 0, Math.PI * 2); ctx.fill();   // ala del sombrero
