            ctx.fillStyle = '#fcfcfc'; ctx.fillRect(-w * 0.17, -h * 0.36, w * 0.34, h * 0.05);                                  // cinta
            ctx.fillStyle = '#ffd848'; ctx.beginPath(); for (let i = 0; i < 10; i++) { const a = -Math.PI / 2 + i * Math.PI / 5, r = i % 2 ? h * 0.025 : h * 0.06; ctx.lineTo(Math.cos(a) * r, -h * 0.335 + Math.sin(a) * r); } ctx.closePath(); ctx.fill();
