    const R = radius(); let dx = e.clientX - cx, dy = e.clientY - cy; const d = Math.hypot(dx, dy) || 1;
    if (d > R) { dx = dx / d * R; dy = dy / d * R; }
    stick.style.transform = `translate(${dx}px, ${dy}px)`;
    let m = Math.min(1, Math.hypot(dx, dy) / R);
    m = m < DEAD ? 0 : Math.pow((m - DEAD) / (1 - DEAD), 1.15);      // respuesta suave: pequeños empujes = movimientos finos
    const ang = Math.atan2(dy, dx);
