    const goRow = el('div', 'th-go'); colR.appendChild(goRow);
    if ($('playBtn')) goRow.appendChild($('playBtn'));
    const back1 = el('button', 'th-back', '◀ VOLVER'); back1.type = 'button'; back1.addEventListener('click', () => show('main')); setup.appendChild(back1);
    root.appendChild(setup);

    // ---- panel Puntajes: pestañas RANKING | MISIONES
    const score = el('div', 'th-panel hidden'); score.id = 'thScore';
    score.innerHTML = '<h2 class="th-ph">PUNTAJES</h2><div class="th-ps">Los mejores pilotos y tus misiones del día</div>' +
        '<div class="th-tabs"><button type="button" class="th-tab on" data-t="rank">★ RANKING</button><button type="button" class="th-tab" data-t="mis">◆ MISIONES</button></div>';
    const board = el('div'); board.id = 'thBoard'; board.innerHTML = '<div class="sb-empty">Cargando puntajes…</div>';
    const misPane = el('div', 'hidden'); misPane.id = 'thMisPane';
    const oldBoard = el('div', 'hidden');                       // el ranking antiguo se conserva oculto (game.js sigue escribiendo en #scoreList)
    if ($('leaderboard')) oldBoard.appendChild($('leaderboard'));
    if ($('missionsBox')) misPane.appendChild($('missionsBox'));
    score.appendChild(board); score.appendChild(misPane); score.appendChild(oldBoard);
    score.querySelectorAll('.th-tab').forEach(t => t.addEventListener('click', () => {
        score.querySelectorAll('.th-tab').forEach(x => x.classList.toggle('on', x === t));
        board.classList.toggle('hidden', t.getAttribute('data-t') !== 'rank'); misPane.classList.toggle('hidden', t.getAttribute('data-t') !== 'mis');
    }));
    const back2 = el('button', 'th-back', '◀ VOLVER'); back2.type = 'button'; back2.addEventListener('click', () => show('main')); score.appendChild(back2);
    root.appendChild(score);
    const fmtN = n => String(Math.max(0, Math.floor(+n || 0))).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
    const DIFF = { facil: ['FÁCIL', '#5fcf8a'], medio: ['MEDIO', '#6cc4ff'], dificil: ['DIFÍCIL', '#ffa23a'], lunatico: ['LUNÁTICO', '#ff3d5c'] };
    const esc = s => { const d = document.createElement('div'); d.textContent = String(s == null ? '' : s); return d.innerHTML; };
    api.renderScores = function (list) {
        if (!list) { board.innerHTML = '<div class="sb-empty">No se pudo cargar el ranking.<br><small>Comprueba que Apache y MySQL estén encendidos.</small></div>'; return; }
        if (!list.length) { board.innerHTML = '<div class="sb-empty">Aún no hay puntajes.<br><small>¡Sé el primer piloto en el ranking!</small></div>'; return; }
        const chip = d => { const x = DIFF[d] || [String(d || '').toUpperCase(), '#aaa']; return '<em class="sb-diff" style="--c:' + x[1] + '">' + esc(x[0]) + '</em>'; };
        const entry = (s, i) => '<div class="sb-name">' + esc(s.player_name) + (s.stars > 0 ? ' <i class="sb-star" title="Se pasó el juego en Lunático">★</i>' : '') + '</div>' + chip(s.difficulty) + '<div class="sb-score" title="' + (s.items === undefined ? '' : 'Ítems: ' + (s.items | 0) + ' · Powerups: ' + (s.powerups | 0) + ' · Monedas: ' + (s.coins | 0) + '/7 · Gemas: ' + (s.gems | 0) + ' · Enemigos: ' + (s.kills | 0)) + '">' + fmtN(s.score) + '</div>';
        let h = '<div class="sb-podium">';
        [1, 0, 2].forEach(i => { const s = list[i]; if (!s) { h += '<div class="sb-slot"></div>'; return; } h += '<div class="sb-pod p' + (i + 1) + '" style="--d:' + (i === 0 ? 0.25 : 0.1 + i * 0.1) + 's"><div class="sb-medal">' + (i === 0 ? '♛' : i + 1) + '</div>' + entry(s, i) + '<div class="sb-base">' + (i + 1) + '°</div></div>'; });
        h += '</div><div class="sb-list">';
        list.slice(3, 10).forEach((s, k) => { h += '<div class="sb-row" style="--d:' + (0.35 + k * 0.05) + 's"><b class="sb-rank">' + (k + 4) + '</b>' + entry(s, k + 3) + '</div>'; });
        board.innerHTML = h + '</div>';
    };

    // ---- Código Konami en el menú principal: ↑ ↑ ↓ ↓ ← → ← → B A  → desbloquea a Reimu y Marisa
    const KONAMI = ['ArrowUp', 'ArrowUp', 'ArrowDown', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'ArrowLeft', 'ArrowRight', 'KeyB', 'KeyA'];
    let kPos = 0;
    const flash = el('div'); flash.id = 'thFlash'; menuUI.appendChild(flash);
    function konami(code) {
        if (code === KONAMI[kPos]) kPos++; else kPos = (code === KONAMI[0]) ? 1 : 0;
        if (kPos < KONAMI.length) return false;
        kPos = 0;
        let had = false;
        try { had = !document.querySelector('.ship-btn[data-ship="5"]').classList.contains('locked') && !document.querySelector('.ship-btn[data-ship="6"]').classList.contains('locked'); } catch (e) {}
        if (had) { sfx('deny'); toastMsg('Código Konami: ya tienes a Reimu y Marisa desbloqueadas.'); return true; }
        try { Extras.dev.coins(7); } catch (e) { toastMsg('No se pudo desbloquear (falta extras.js).'); return true; }
        flash.classList.remove('go'); void flash.offsetWidth; flash.classList.add('go');
        sfx('play'); setTimeout(() => sfx('lunatic'), 160);
        toastMsg('★ ¡CÓDIGO KONAMI! Reimu y Marisa desbloqueadas ★'); renderHangar();
        return true;
    }

    // ---- OPCIONES: se reorganiza el modal existente en pestañas (los inputs conservan sus ids)
    function buildOptions() {
        const box = document.querySelector('#optionsModal .options-box'); if (!box) return;
        const rows = {};
        box.querySelectorAll('.options-row').forEach(r => { const c = r.querySelector('input,select,span[id]'); if (c && c.id) rows[c.id] = r; });
        const fs = $('btnFullscreen'), closeB = $('btnCloseOptions');
        const INFO = {
            optLives: ['♥', 'Vidas iniciales', 'Con cuántas vidas empiezas cada partida (1 a 10).'],
            optPerformance: ['⚡', 'Modo Rendimiento', 'Menos partículas y efectos para equipos modestos.'],
            optCRT: ['▤', 'Efecto CRT retro', 'Líneas de barrido y viñeta como un monitor antiguo.'],
            optWidescreen: ['▥', 'HUD compacto', 'Panel lateral más angosto: más espacio para jugar.'],
            optVerticalMode: ['▮', 'Modo vertical (estilo Touhou)', 'Área de juego en vertical con el panel a la derecha. Solo PC.'],
            optMobile: ['☎', 'Modo teléfono', 'Muestra el joystick y los botones en pantalla.'],
            optTouchFloat: ['◉', 'Joystick flotante', 'Aparece donde apoyes el pulgar.'],
            optTouchLefty: ['◐', 'Modo zurdo', 'Joystick a la derecha y botones a la izquierda.'],
            optTouchAuto: ['✦', 'Disparo automático', 'Dispara sin parar mientras juegas (botón AUTO).'],
            optTouchVibe: ['≋', 'Vibración', 'Vibra al disparar, usar bomba o recibir un golpe.'],
            optTouchSize: ['⬡', 'Tamaño de controles', 'Qué tan grandes se ven los botones táctiles.'],
            optTouchOpacity: ['◌', 'Transparencia', 'Qué tan visibles se ven los controles.'],
            optMusicVol: ['♪', 'Volumen de música', 'Qué tan fuerte suena la música de fondo.']
        };
        const decorate = id => {
            const r = rows[id], inf = INFO[id]; if (!r) return null;
            r.classList.add('op-card');
            const lab = r.querySelector('label'); if (lab && inf) { const t = lab.childNodes; for (let i = 0; i < t.length; i++) if (t[i].nodeType === 3 && t[i].textContent.trim()) t[i].textContent = inf[1]; }
            const d = el('div', 'op-desc', inf ? inf[2] : ''); r.appendChild(d);
            r.insertBefore(el('div', 'op-ico', inf ? inf[0] : '◆'), r.firstChild);
            return r;
        };
        const lv = rows.optLives;
        if (lv) {      // vidas: botones − / +
            lv.classList.add('op-card', 'op-lives'); const inf = INFO.optLives;
            const inp = $('optLives'); lv.innerHTML = ''; const l2 = el('div', 'op-lt', '<b>' + inf[1] + '</b><small>' + inf[2] + '</small>'); lv.appendChild(el('div', 'op-ico', inf[0])); lv.appendChild(l2);
            const st = el('div', 'op-step'); const m = el('button', null, '−'), p = el('button', null, '+'); m.type = p.type = 'button';
            st.appendChild(m); st.appendChild(inp); st.appendChild(p); lv.appendChild(st);
            const bump = d => { inp.value = clamp((parseInt(inp.value, 10) || 3) + d, 1, 10); inp.dispatchEvent(new Event('change', { bubbles: true })); };
            m.addEventListener('click', () => bump(-1)); p.addEventListener('click', () => bump(1));
        }
        ['optPerformance', 'optMusicVol', 'optCRT', 'optWidescreen', 'optVerticalMode', 'optMobile', 'optTouchFloat', 'optTouchLefty', 'optTouchAuto', 'optTouchVibe', 'optTouchSize', 'optTouchOpacity'].forEach(decorate);
        const TABS = [
            ['JUEGO', '♥', [lv, rows.optPerformance, rows.optMusicVol, rows.perfDetectedLabel, rows.runNote]],
            ['PANTALLA', '▤', [rows.optCRT, rows.optWidescreen, rows.optVerticalMode, 'FS']],
            ['CONTROLES', '☎', [rows.optMobile, rows.deviceDetectedLabel, rows.optTouchFloat, rows.optTouchLefty, rows.optTouchAuto, rows.optTouchVibe, rows.optTouchSize, rows.optTouchOpacity]]
        ];
        box.innerHTML = '';
        box.appendChild(el('h2', 'op-title', 'OPCIONES'));
        box.appendChild(el('div', 'op-sub', 'Ajusta el juego a tu gusto'));
        const bar = el('div', 'th-tabs'), panes = [];
        TABS.forEach((T, i) => {
            const tb = el('button', 'th-tab' + (i ? '' : ' on'), '<span>' + T[1] + '</span> ' + T[0]); tb.type = 'button';
            const pane = el('div', 'op-pane' + (i ? ' hidden' : ''));
            T[2].forEach(x => {
                if (x === 'FS') { if (fs) { pane.appendChild(fs); } pane.appendChild(el('div', 'op-note', 'La pantalla completa también se activa sola al pulsar JUGAR.')); }
                else if (x) { if (x.querySelector && x.querySelector('#deviceDetectedLabel,#perfDetectedLabel')) x.classList.add('op-info'); pane.appendChild(x); }
            });
            tb.addEventListener('click', () => { bar.querySelectorAll('.th-tab').forEach(z => z.classList.toggle('on', z === tb)); panes.forEach(p => p.classList.toggle('hidden', p !== pane)); box.scrollTop = 0; });
            bar.appendChild(tb); panes.push(pane);
        });
        box.appendChild(bar); const wrap = el('div', 'op-panes'); panes.forEach(p => wrap.appendChild(p)); box.appendChild(wrap);
        if (closeB) { closeB.className = 'th-back op-close'; closeB.textContent = '◀ VOLVER'; box.appendChild(closeB); }
    }

    // ---- pantalla de salida
    const quitEl = el('div', null, '<h2>GRACIAS POR JUGAR</h2><p>PRESIONA UNA TECLA</p>'); quitEl.id = 'thQuit';
    menuUI.appendChild(quitEl);

    function toastMsg(msg) { toast.textContent = msg; toast.classList.add('on'); clearTimeout(toastMsg.t); toastMsg.t = setTimeout(() => toast.classList.remove('on'), 2600); }
    const sfx = n => { try { MenuSFX.play(n); } catch (e) {} };

    function setIdx(i, quiet) {
        idx = (i + ITEMS.length) % ITEMS.length;
        ITEMS.forEach((it, k) => it.btn.classList.toggle('sel', k === idx));
        const it = ITEMS[idx];
        caption.textContent = (it.id === 'practice' && !data.clear) ? 'BLOQUEADO — pásate el juego (6 niveles) para abrirlo.' : it.cap;
    }
    function refreshLocks() {
        try { renderHangar(); } catch (e) {}
        ITEMS[1].btn.classList.toggle('locked', !data.clear);
        stageBtns.forEach((b, k) => {
            const n = k + 1, lock = n === 7 ? !data.l7 : false;
            b.classList.toggle('locked', lock);
            b.classList.toggle('sel', n === practiceSel);
            b.querySelector('small').textContent = n === 7 ? (data.l7 ? 'solo en Lunático' : '🔒 pásate el juego en Lunático') : '';
        });
        setIdx(idx, true);
    }
    function clickChip(group, value) { const c = document.querySelector('.chip-group[data-for="' + group + '"] .chip[data-value="' + value + '"]'); if (c) c.click(); }
    function pickStage(n) {
        if (n === 7 && !data.l7) { stageBtns[6].classList.remove('shake'); void stageBtns[6].offsetWidth; stageBtns[6].classList.add('shake'); sfx('deny'); toastMsg('Nivel 7: pásate el juego en LUNÁTICO para desbloquearlo.'); return; }
        practiceSel = n; api.pendingPractice = n;
        if (n === 7 && diffSel && diffSel.value !== 'lunatico') clickChip('difficulty', 'lunatico');   // el nivel 7 solo existe en Lunático
        refreshLocks();
    }
    if (diffSel) diffSel.addEventListener('change', () => {     // si se deja Lunático, el nivel 7 deja de existir
        if (screen === 'practice' && practiceSel === 7 && diffSel.value !== 'lunatico') { practiceSel = 6; api.pendingPractice = 6; refreshLocks(); }
    });

    // ---- SECRETO: tocar 50 veces la nave del menú principal desbloquea el Modo Práctica con los 7 niveles
    const SECRET_TAPS = 50;
    let tapN = 0, tapT = 0;
    function secretShipTap(e) {
        if (screen !== 'main' || introOn) return;
        if (e.target && e.target.closest && e.target.closest('button, a, select, input, .th-item')) return;   // no robar clics del menú
        const r = cv.getBoundingClientRect(); if (!r.width || !r.height) return;
        const x = (e.clientX - r.left) / r.width * W, y = (e.clientY - r.top) / r.height * H;
        if (Math.abs(x - L.sx) > L.ss * 0.85 || y < L.sy - L.ss * 1.05 || y > L.sy + L.ss * 1.2) return;     // fuera de la nave
        const now2 = performance.now();
        if (now2 - tapT > 3000) tapN = 0;                  // si te detienes más de 3 s, se reinicia la cuenta
        tapT = now2;
        if (data.clear && data.l7) { if (++tapN === 3) toastMsg('El Modo Práctica ya está desbloqueado (7 niveles).'); return; }
        tapN++;
        if (tapN >= SECRET_TAPS) {
            tapN = 0; data.clear = true; data.l7 = true; saveData(); refreshLocks();
            sfx('play'); setTimeout(() => sfx('lunatic'), 160);
            toastMsg('¡MODO PRÁCTICA DESBLOQUEADO! Los 7 niveles están disponibles.');
        } else {
            sfx('ship', tapN % 6);
            if (tapN >= 30) toastMsg('La nave vibra... ' + (SECRET_TAPS - tapN) + ' toques más.');
        }
    }
    menuUI.addEventListener('pointerdown', secretShipTap);

    // ---- KONAMI TÁCTIL (teléfono): con un dedo, en el menú principal:
    //      desliza ↑ ↑ ↓ ↓ ← → ← →  y luego toca la NAVE (= B) y la LUNA (= A). Mismo premio que el código del teclado.
    //      Un toque en otro sitio no rompe la secuencia; deslizar mal o tocar la nave/luna fuera de turno, sí.
    const SWIPE_MIN = 36, SWIPE_DIR = { up: 'ArrowUp', down: 'ArrowDown', left: 'ArrowLeft', right: 'ArrowRight' };
    let gId = null, gx = 0, gy = 0, gt = 0;
    function konamiStep(code) {
        const before = kPos, done = konami(code);
        if (!done && kPos > before) sfx('ship', kPos % 6);          // pitido de progreso
    }
    function konamiActive() { return screen === 'main' && !introOn && !(quitEl && quitEl.classList.contains('on')); }
    menuUI.addEventListener('pointerdown', e => {
        if (!konamiActive() || !e.isPrimary) { gId = null; return; }
        gId = e.pointerId; gx = e.clientX; gy = e.clientY; gt = performance.now();
    });
    menuUI.addEventListener('pointercancel', () => { gId = null; });
    menuUI.addEventListener('pointerup', e => {
        if (e.pointerId !== gId) return; gId = null;
        if (!konamiActive()) return;
        const dx = e.clientX - gx, dy = e.clientY - gy, dist = Math.hypot(dx, dy), dt = performance.now() - gt;
        if (dist >= SWIPE_MIN) {                                      // deslizamiento
            const dir = Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? 'right' : 'left') : (dy > 0 ? 'down' : 'up');
            konamiStep(SWIPE_DIR[dir]); return;
        }
        if (dist > 14 || dt > 500) return;                            // ni toque ni deslizamiento
        if (e.target && e.target.closest && e.target.closest('button, a, select, input, .th-item')) return;
        const r = cv.getBoundingClientRect(); if (!r.width || !r.height) return;
        const x = (e.clientX - r.left) / r.width * W, y = (e.clientY - r.top) / r.height * H;
        if (Math.hypot(x - L.mx, y - L.my) <= L.mr * 1.5) { konamiStep('KeyA'); return; }                 // luna
        if (Math.abs(x - L.sx) <= L.ss * 0.85 && y >= L.sy - L.ss * 1.05 && y <= L.sy + L.ss * 1.2) konamiStep('KeyB');   // nave
    });
    // sin esto el navegador móvil convierte el deslizamiento en scroll y cancela el gesto
    function syncTouch() { menuUI.style.touchAction = screen === 'main' ? 'none' : ''; }
    syncTouch();

    function show(s) {
        const was = screen; screen = s;
        setup.classList.toggle('hidden', s !== 'setup' && s !== 'practice');
        setup.classList.toggle('practice', s === 'practice');
        score.classList.toggle('hidden', s !== 'score');
        list.style.display = (s === 'main') ? '' : 'none';
        stagesSec.style.display = (s === 'practice') ? '' : 'none';
        // el Modo Práctica siempre es Moderno: se recuerda el modo anterior para restaurarlo al salir
        if (s === 'practice' && modeSel && prevMode === null) { prevMode = modeSel.value; clickChip('gameMode', 'moderno'); }
        if (s !== 'practice' && prevMode !== null) { clickChip('gameMode', prevMode); prevMode = null; }
        api.pendingPractice = (s === 'practice') ? practiceSel : 0;
        if (s === 'setup' || s === 'practice') {
            $('thSetupTitle').textContent = s === 'practice' ? 'MODO PRÁCTICA' : 'COMENZAR';
            $('thSetupSub').textContent = s === 'practice' ? 'Un solo nivel · no guarda puntaje ni misiones  ·  ←→ nave · ↑↓ nivel · Q/E dificultad' : 'Elige nave, dificultad y modo  ·  ←→ nave · ↑↓ dificultad';
            prev = currentShip(); renderHangar();
            if ($('playBtn')) $('playBtn').textContent = s === 'practice' ? '▶ PRACTICAR' : '▶ JUGAR';
            if (s === 'practice') { if (practiceSel === 7 && diffSel && diffSel.value !== 'lunatico') practiceSel = 6; refreshLocks(); }
            setup.scrollTop = 0;
        }
        syncTouch();
        if (s === 'main') { menuUI.classList.remove('th-sub'); setIdx(idx, true); }
        if (was !== s && s === 'score') { try { loadScores(); } catch (e) {} }
    }
    function activate(id) {
        if (id === 'start') return show('setup');
        if (id === 'practice') {
            if (!data.clear) { sfx('deny'); toastMsg('Practice Start: pásate el juego con sus 6 niveles para desbloquearlo.'); it0shake(); return; }
            return show('practice');
        }
        if (id === 'score') return show('score');
        if (id === 'shop') { const b = $('btnShop'); if (b) b.click(); else toastMsg('La tienda no está disponible.'); return; }
        if (id === 'option') { const b = $('btnOptionsToggle'); if (b) b.click(); return; }
        if (id === 'install') { if (window.InstallApp) window.InstallApp.open(); else toastMsg('La instalación no está disponible (falta instalar.js).'); return; }
        if (id === 'credits') { if (window.Creditos) window.Creditos.open(); else toastMsg('Los créditos no están disponibles (falta creditos.js).'); return; }
        if (id === 'quit') return doQuit();
    }
    function it0shake() { const b = ITEMS[1].btn; b.classList.remove('shake'); void b.offsetWidth; b.classList.add('shake'); }
    function doQuit() {
        quitEl.classList.add('on'); requestAnimationFrame(() => quitEl.classList.add('vis'));
        try { MenuMusic.stop(true); } catch (e) {}
    }
    function leaveQuit() {
        quitEl.classList.remove('vis'); setTimeout(() => quitEl.classList.remove('on'), 800);
        setIdx(0, true); beginIntro();
    }

    // ------------------------------------------------------------------ teclado / puntero
    const modalOpen = () => { const o = $('optionsModal'), s = $('shopModal'); return (o && !o.classList.contains('hidden')) || (s && !s.classList.contains('hidden')); };
    window.addEventListener('keydown', e => {
        if (menuUI.classList.contains('hidden') || (typeof isMenu !== 'undefined' && !isMenu)) return;
        if (Date.now() < (window.__menuLockUntil || 0)) { e.preventDefault(); e.stopPropagation(); return; }   // v39: recién volviste de la partida
        if (quitEl.classList.contains('on')) { e.preventDefault(); e.stopPropagation(); if (quitEl.classList.contains('vis')) leaveQuit(); return; }
        if (introOn) { e.preventDefault(); e.stopPropagation(); skipIntro(); return; }
        const om = $('optionsModal');
        if (om && !om.classList.contains('hidden')) { if ((e.code === 'Escape' || e.code === 'KeyX') && !(e.target && e.target.tagName === 'SELECT')) { e.preventDefault(); e.stopPropagation(); const c = $('btnCloseOptions'); if (c) c.click(); } return; }
        if (modalOpen()) return;
        const typing = e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT');
        const k = e.code;
        const ok = k === 'Enter' || k === 'KeyZ' || k === 'NumpadEnter', bk = k === 'Escape' || k === 'KeyX';
        if (ok && e.repeat) { e.preventDefault(); e.stopPropagation(); return; }   // v39: mantener ENTER/Z pulsado nunca activa botones del menú (evitaba reiniciar solo desde el nivel 1)
        if (typing && !(k === 'Escape' || (k === 'Enter'))) return;
        if (typing && k === 'Enter') { e.target.blur(); e.preventDefault(); return; }
        if (screen === 'main' && konami(k)) { e.preventDefault(); e.stopPropagation(); return; }
        if (screen === 'main') {
            if (k === 'ArrowUp') { setIdx(idx - 1); sfx('hover'); } else if (k === 'ArrowDown') { setIdx(idx + 1); sfx('hover'); }
            else if (ok) { ITEMS[idx].btn.click(); }
            else if (bk) { if (idx !== ITEMS.length - 1) { setIdx(ITEMS.length - 1); sfx('back'); } }
            else return;
        } else {
            const diffs = ['facil', 'medio', 'dificil', 'lunatico'];
            if (bk) { sfx('back'); show('main'); }
            else if ((k === 'ArrowLeft' || k === 'ArrowRight') && (screen === 'setup' || screen === 'practice')) { const a = hangar.querySelector('.hg-arrow[data-d="' + (k === 'ArrowRight' ? 1 : -1) + '"]'); if (a) a.click(); }
            else if (((k === 'KeyQ' || k === 'KeyE') && screen === 'practice' || (screen === 'setup' && (k === 'ArrowUp' || k === 'ArrowDown'))) && diffSel) {
                const dir = (k === 'ArrowDown' || k === 'KeyE') ? 1 : -1, i = diffs.indexOf(diffSel.value), j = clamp(i + dir, 0, 3); if (j !== i) clickChip('difficulty', diffs[j]);
            } else if (screen === 'score' && (k === 'ArrowLeft' || k === 'ArrowRight')) { const t = score.querySelector('.th-tab:not(.on)'); if (t) t.click();
            } else if (screen === 'practice' && (k === 'ArrowUp' || k === 'ArrowDown')) {
                let n = practiceSel + (k === 'ArrowDown' ? 1 : -1); n = clamp(n, 1, 7); if (n === 7 && !data.l7) n = 6; if (n !== practiceSel) { pickStage(n); sfx('hover'); }
            } else if (ok && (screen === 'setup' || screen === 'practice')) { const pb = $('playBtn'); if (pb) pb.click(); }
            else return;
        }
        e.preventDefault(); e.stopPropagation();
    }, true);
    menuUI.addEventListener('pointerdown', () => { if (introOn) skipIntro(); });
    quitEl.addEventListener('click', () => { if (quitEl.classList.contains('vis')) leaveQuit(); });
    cv.addEventListener('pointerdown', () => { if (introOn) skipIntro(); });

    // ------------------------------------------------------------------ mostrar / ocultar con el menú
    let wasHidden = menuUI.classList.contains('hidden');
    function onMenuToggle() {
        const h = menuUI.classList.contains('hidden');
        if (h === wasHidden) return; wasHidden = h;
        if (h) stop();
        else { introOn = false; startAt = performance.now() - INTRO_END; menuUI.classList.remove('th-intro'); if (screen !== 'main') show('main'); refreshLocks(); start(); }
    }
    new MutationObserver(onMenuToggle).observe(menuUI, { attributes: true, attributeFilter: ['class'] });

    api.dev.intro = function () { start(); beginIntro(); };
    api.show = show;

