        g.addColorStop(0.64, 'rgba(170,225,255,' + 0.92 * life + ')'); g.addColorStop(0.84, 'rgba(60,150,255,' + 0.7 * life + ')'); g.addColorStop(1, 'rgba(30,110,255,0)');
