            for (let j = enemyBullets.length - 1; j >= 0; j--) { const e = enemyBullets[j]; if (Math.abs(e.x - cx) < w / 2 + 6 && e.y < yTop && !bossBulletsImmune()) enemyBullets.splice(j, 1); }
