/* ===== pausa_ajustes.js ===== */
// Pausa → AJUSTES: abre el panel de configuración sobre la pausa. Lo que cambia el tamaño del área de juego
// o la partida (vidas, modo teléfono, HUD, modo vertical) se bloquea mientras juegas. Volumen de música incluido.
(function () {
    'use strict';
    const $ = id => document.getElementById(id);
    const modal = $('optionsModal'), btn = $('btnPauseSettings'), close = $('btnCloseOptions'), menuBtn = $('btnOptionsToggle'), vol = $('optMusicVol');
    if (!modal) return;
    const KEY = 'sg_music_vol';
    function applyVol(v) {
        const g = 0.5 * Math.max(0, Math.min(100, v)) / 100;      // 50 % = 0.25 (el volumen de siempre)
        try { setBgmVolume(g); } catch (e) {}
    }
    if (vol) {
        let v = 50; try { const sv = localStorage.getItem(KEY); if (sv !== null) v = parseInt(sv, 10); } catch (e) {}
        if (isNaN(v)) v = 50; vol.value = v; applyVol(v);
        vol.addEventListener('input', () => { const n = parseInt(vol.value, 10); applyVol(n); try { localStorage.setItem(KEY, String(n)); } catch (e) {} });
    }
    if (btn) btn.addEventListener('click', () => { modal.classList.add('in-run'); modal.classList.remove('hidden'); });
    if (close) close.addEventListener('click', () => modal.classList.remove('in-run'));
    if (menuBtn) menuBtn.addEventListener('click', () => modal.classList.remove('in-run'));
    // Esc con los ajustes abiertos en pausa: solo cierra los ajustes (no reanuda la partida)
    window.addEventListener('keydown', e => {
        if (e.code === 'Escape' && modal.classList.contains('in-run') && !modal.classList.contains('hidden')) {
            e.preventDefault(); e.stopPropagation(); modal.classList.add('hidden'); modal.classList.remove('in-run');
        }
    }, true);
})();

